def _roadmap_scorecard_readiness_detail(evidence: dict[str, str]) -> str:
    parts: list[str] = []
    for label in ("baseline", "candidate"):
        fail_count = _evidence_int(evidence, f"{label}_scorecard_readiness_fail_count")
        reason_summary = evidence.get(f"{label}_scorecard_not_ready_reason_codes", "").strip()
        fail_reason_summary = evidence.get(f"{label}_scorecard_fail_reason_codes", "").strip()
        proxy_summary = evidence.get(f"{label}_scorecard_not_ready_proxy_metrics", "").strip()
        if not proxy_summary or proxy_summary == "-":
            proxy_summary = evidence.get(f"{label}_scorecard_first_not_ready_proxy_metrics", "").strip()
        fail_proxy_summary = evidence.get(f"{label}_scorecard_fail_proxy_metrics", "").strip()
        repair_target_summary = evidence.get(f"{label}_scorecard_not_ready_repair_targets", "").strip()
        fail_repair_target_summary = evidence.get(f"{label}_scorecard_fail_repair_targets", "").strip()
        fail_ids = _format_evidence_csv_items(
            evidence.get(f"{label}_scorecard_fail_candidate_ids", "")
        )
        not_ready_ids = _format_evidence_csv_items(
            evidence.get(f"{label}_scorecard_not_ready_candidate_ids", "")
        )
        if fail_count <= 0 and not (reason_summary and reason_summary != "-"):
            continue
        detail = f"{label}"
        if fail_count > 0:
            detail += f" fail_count={fail_count}"
        if fail_reason_summary and fail_reason_summary != "-":
            detail += f" fail_reason_codes={fail_reason_summary}"
        if reason_summary and reason_summary != "-":
            detail += f" reason_codes={reason_summary}"
        if fail_ids:
            detail += f" fail_ids={fail_ids}"
        if not_ready_ids:
            detail += f" non_pass_ids={not_ready_ids}"
        if fail_proxy_summary and fail_proxy_summary != "-":
            detail += f" fail_proxy_metrics={fail_proxy_summary}"
        if proxy_summary and proxy_summary != "-":
            detail += f" proxy_metrics={proxy_summary}"
        if fail_repair_target_summary and fail_repair_target_summary != "-":
            detail += f" fail_repair_targets={fail_repair_target_summary}"
        if repair_target_summary and repair_target_summary != "-":
            detail += f" repair_targets={repair_target_summary}"
        parts.append(detail)
    if not parts:
        return ""
    return f" ({'; '.join(parts)})"


def _roadmap_scorecard_source_sidecar_repair_needed(evidence: dict[str, str]) -> bool:
    source_sidecar_prefixes = ("coverage_",)
    for label in ("baseline", "candidate"):
        for key in (
            f"{label}_scorecard_fail_reason_codes",
            f"{label}_scorecard_not_ready_reason_codes",
        ):
            summary = evidence.get(key, "").strip()
            if not summary or summary == "-":
                continue
            for item in summary.split(","):
                code = item.split(":", 1)[0].strip()
                if any(code.startswith(prefix) for prefix in source_sidecar_prefixes):
                    return True
    return False


def _roadmap_scorecard_gold_label_repair_needed(evidence: dict[str, str]) -> bool:
    for label in ("baseline", "candidate"):
        for key in (
            f"{label}_scorecard_fail_reason_codes",
            f"{label}_scorecard_not_ready_reason_codes",
        ):
            summary = evidence.get(key, "").strip()
            if not summary or summary == "-":
                continue
            for item in summary.split(","):
                code = item.split(":", 1)[0].strip()
                if code == "gold_labels_missing":
                    return True
    return False


def _external_contract_scorecard_backfill_source_sidecar_repair_needed(evidence: dict[str, str]) -> bool:
    failed_schema_findings = evidence.get("failed_contract_schema_findings", "").strip()
    if (
        not failed_schema_findings
        or failed_schema_findings == "-"
        or "evidence_grounding_scorecard_input_backfill.v1:scorecard_input_backfill_scorecard_failure_details"
        not in failed_schema_findings
    ):
        return False
    for finding in failed_schema_findings.split(";"):
        if "scorecard_input_backfill_scorecard_failure_details" not in finding:
            continue
        if "reason_codes=" not in finding:
            continue
        reason_codes = finding.split("reason_codes=", 1)[1]
        for code in reason_codes.split(","):
            if code.strip().startswith("coverage_"):
                return True
    return False


def _external_contract_scorecard_backfill_gold_label_repair_needed(evidence: dict[str, str]) -> bool:
    failed_schema_findings = evidence.get("failed_contract_schema_findings", "").strip()
    return (
        bool(failed_schema_findings)
        and failed_schema_findings != "-"
        and "evidence_grounding_scorecard_input_backfill.v1:scorecard_input_backfill_scorecard_failure_details"
        in failed_schema_findings
        and "gold_labels_missing" in failed_schema_findings
    )


def _external_contract_scorecard_backfill_generation_repair_needed(evidence: dict[str, str]) -> bool:
    failed_schema_findings = evidence.get("failed_contract_schema_findings", "").strip()
    if (
        not failed_schema_findings
        or failed_schema_findings == "-"
        or "evidence_grounding_scorecard_input_backfill.v1:" not in failed_schema_findings
    ):
        return False
    return (
        "scorecard_input_backfill_scorecard_coverage_mismatch" in failed_schema_findings
        or "scorecard_input_backfill_scorecard_artifacts_missing" in failed_schema_findings
    )


def _format_evidence_list_items(value: str) -> str:
    value = value.strip()
    if not value or value == "-":
        return ""
    return value


def _format_evidence_csv_items(value: str) -> str:
    value = value.strip()
    if not value or value == "-":
        return ""
    return value


def _format_evidence_csv_item_sample(value: str, *, limit: int = 3) -> str:
    value = value.strip()
    if not value or value == "-":
        return ""
    items = [item.strip() for item in value.split(",") if item.strip()]
    if not items:
        return ""
    sample = items[:limit]
    if len(items) > limit:
        sample.append(f"...{len(items) - limit}_more")
    return ",".join(sample)


def _format_evidence_context_key_map_sample(
    value: str,
    *,
    field_limit: int = 3,
    key_limit: int = 3,
) -> str:
    value = value.strip()
    if not value or value == "-":
        return ""
    items = [item.strip() for item in value.split(",") if item.strip()]
    sampled_items: list[str] = []
    for item in items[:field_limit]:
        field_name, separator, raw_keys = item.partition(":")
        if not separator:
            sampled_items.append(item)
            continue
        keys = [key.strip() for key in raw_keys.split("|") if key.strip()]
        sampled_keys = keys[:key_limit]
        if len(keys) > key_limit:
            sampled_keys.append(f"...{len(keys) - key_limit}_more")
        sampled_items.append(f"{field_name}:{'|'.join(sampled_keys)}")
    if len(items) > field_limit:
        sampled_items.append(f"...{len(items) - field_limit}_more")
    return ",".join(sampled_items)


def _evidence_csv_count(value: str) -> int:
    value = value.strip()
    if not value or value == "-":
        return 0
    return len([item for item in (part.strip() for part in value.split(",")) if item])


def _evidence_candidate_id_split_counts(value: str, *, covered_splits: str) -> str:
    candidate_ids = [item for item in (part.strip() for part in value.split(",")) if item]
    if not candidate_ids:
        return ""
    split_names = [item for item in (part.strip() for part in covered_splits.split(",")) if item]
    if not split_names:
        split_names = ["seed", "eval", "holdout"]
    counts = {split: 0 for split in split_names}
    for candidate_id in candidate_ids:
        for split in split_names:
            if f"-{split}:" in candidate_id or candidate_id.startswith(f"{split}:"):
                counts[split] += 1
                break
    return ",".join(f"{split}:{count}" for split, count in counts.items() if count > 0)


def _roadmap_workspace_evidence(checks: list[EvidenceGroundingRoadmapCompletionCheck]) -> dict[str, str]:
    workspace_evidence: dict[str, str] = {}
    for check in checks:
        if check.requirement_id == "workspace_evidence_inventory_ready":
            workspace_evidence.update(_evidence_key_values(check.evidence))
            break
    for check in checks:
        if check.requirement_id != "candidate_configuration_lineage":
            continue
        candidate_lineage_evidence = _evidence_key_values(check.evidence)
        for key in ("candidate_lineage_run_dir_map_path",):
            value = candidate_lineage_evidence.get(key, "").strip()
            if value and value != "-":
                workspace_evidence.setdefault(key, value)
    return workspace_evidence


def _roadmap_next_action_phase_counts(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for action in actions:
        phase = (action.phase or "unknown").strip() or "unknown"
        counts[phase] = counts.get(phase, 0) + 1
    return dict(sorted(counts.items()))


def _roadmap_next_action_counts_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        if not requirement_id:
            continue
        counts[requirement_id] = counts.get(requirement_id, 0) + 1
    return dict(sorted(counts.items()))


def _roadmap_next_action_texts_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    texts_by_requirement: dict[str, list[str]] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        action_text = action.action.strip()
        if not requirement_id or not action_text:
            continue
        texts_by_requirement.setdefault(requirement_id, []).append(action_text)
    return dict(sorted(texts_by_requirement.items()))


def _roadmap_next_action_command_hints_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    hints_by_requirement: dict[str, list[str]] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        command_hint = (action.command_hint or "").strip()
        if not requirement_id or not command_hint:
            continue
        hints_by_requirement.setdefault(requirement_id, []).append(command_hint)
    return dict(sorted(hints_by_requirement.items()))


def _roadmap_next_action_unresolved_command_placeholders_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    placeholders_by_requirement: dict[str, list[str]] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        command_hint = (action.command_hint or "").strip()
        placeholders = _roadmap_command_hint_unresolved_placeholders(command_hint)
        if not requirement_id or not placeholders:
            continue
        placeholders_by_requirement.setdefault(requirement_id, []).extend(placeholders)
    return dict(sorted(placeholders_by_requirement.items()))


def _roadmap_next_action_unresolved_command_placeholder_counts_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    return {
        requirement_id: len(placeholders)
        for requirement_id, placeholders in _roadmap_next_action_unresolved_command_placeholders_by_requirement(
            actions
        ).items()
    }


def _roadmap_next_action_unresolved_command_placeholder_counts_by_placeholder(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for placeholders in _roadmap_next_action_unresolved_command_placeholders_by_requirement(
        actions
    ).values():
        for placeholder in placeholders:
            counts[placeholder] = counts.get(placeholder, 0) + 1
    return dict(sorted(counts.items()))


def _roadmap_next_action_blocked_by_requirement_ids_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    values_by_requirement: dict[str, list[str]] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        values = [
            item.strip()
            for item in action.blocked_by_requirement_ids
            if item.strip()
        ]
        if requirement_id and values:
            values_by_requirement.setdefault(requirement_id, []).extend(values)
    return dict(sorted(values_by_requirement.items()))


def _roadmap_next_action_blocked_by_requirement_counts(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for blocked_ids in _roadmap_next_action_blocked_by_requirement_ids_by_requirement(
        actions
    ).values():
        for requirement_id in blocked_ids:
            counts[requirement_id] = counts.get(requirement_id, 0) + 1
    return dict(sorted(counts.items()))


def _roadmap_next_action_blocked_by_requirement_unique_ids_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    unique_by_requirement: dict[str, list[str]] = {}
    for requirement_id, blocked_ids in (
        _roadmap_next_action_blocked_by_requirement_ids_by_requirement(actions).items()
    ):
        seen: set[str] = set()
        values: list[str] = []
        for blocked_id in blocked_ids:
            if blocked_id in seen:
                continue
            seen.add(blocked_id)
            values.append(blocked_id)
        if values:
            unique_by_requirement[requirement_id] = values
    return dict(sorted(unique_by_requirement.items()))


def _roadmap_next_action_blocked_by_requirement_unique_counts(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for blocked_ids in (
        _roadmap_next_action_blocked_by_requirement_unique_ids_by_requirement(
            actions
        ).values()
    ):
        for requirement_id in blocked_ids:
            counts[requirement_id] = counts.get(requirement_id, 0) + 1
    return dict(sorted(counts.items()))


def _roadmap_next_action_blocker_reasons_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
    *,
    missing_metric_inputs_by_requirement: dict[str, list[str]],
    human_review_open_task_ids_by_requirement: dict[str, list[str]],
) -> dict[str, list[str]]:
    reasons_by_requirement: dict[str, list[str]] = {}
    seen_requirement_ids_with_prior_action: set[str] = set()
    for action in actions:
        requirement_id = action.requirement_id.strip()
        if not requirement_id:
            continue
        action_text = action.action.strip()
        command_hint = (action.command_hint or "").strip()
        has_prior_prerequisite = requirement_id in seen_requirement_ids_with_prior_action
        if action_text:
            seen_requirement_ids_with_prior_action.add(requirement_id)
        if action.requires_human_review:
            kind = "human_review_with_command" if command_hint else "human_review_without_command"
        elif not command_hint:
            kind = "nonhuman_without_command"
        elif _roadmap_command_hint_has_unresolved_placeholder(command_hint):
            kind = "placeholder_command"
        elif has_prior_prerequisite:
            kind = "prerequisite_gated_command"
        else:
            kind = "ready_to_run_command"
        reasons = _roadmap_next_action_blocker_reasons(
            kind=kind,
            requires_human_review=action.requires_human_review,
            has_command_hint=bool(command_hint),
            has_prior_prerequisite=has_prior_prerequisite,
            unresolved_command_placeholders=(
                _roadmap_command_hint_unresolved_placeholders(command_hint)
            ),
            missing_metric_inputs=missing_metric_inputs_by_requirement.get(
                requirement_id,
                [],
            ),
            human_review_open_task_ids=human_review_open_task_ids_by_requirement.get(
                requirement_id,
                [],
            ),
            blocked_by_requirement_ids=[
                item.strip()
                for item in action.blocked_by_requirement_ids
                if item.strip()
            ],
        )
        if reasons:
            reasons_by_requirement.setdefault(requirement_id, []).extend(reasons)
    return dict(sorted(reasons_by_requirement.items()))


