def _roadmap_merge_requirement_id_lists(*values: list[str]) -> list[str]:
    merged: list[str] = []
    for raw_values in values:
        for raw_value in raw_values:
            value = raw_value.strip()
            if value and value not in merged:
                merged.append(value)
    return merged


