def _load_optional_audit_model(
    path: Path | None,
    model: type,
    *,
    label: str,
    warnings: list[str],
):
    if path is None:
        warnings.append(f"{label}_path_missing")
        return None
    try:
        return model.model_validate(_load_json_object(path))
    except (OSError, ValueError, ValidationError, RuntimeError) as exc:
        warnings.append(f"{label}_load_failed: {exc}")
        return None


def _roadmap_paths_from_comparison_suite(
    comparison_suite_path: Path | None,
) -> tuple[dict[str, Path], list[str]]:
    if comparison_suite_path is None:
        return {}, []
    try:
        payload = _load_json_object(comparison_suite_path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return {}, [f"comparison_suite_load_failed: {exc}"]
    base_dir = comparison_suite_path.parent
    mapping = {
        "baseline_benchmark_manifest_path": payload.get("baseline_manifest_path"),
        "candidate_benchmark_manifest_path": payload.get("candidate_manifest_path"),
        "baseline_benchmark_report_path": payload.get("baseline_report_path"),
        "candidate_benchmark_report_path": payload.get("candidate_report_path"),
        "comparison_report_path": payload.get("comparison_report_path"),
        "run_readiness_report_path": payload.get("run_readiness_report_path"),
    }
    optional_path_keys = {
        "baseline_benchmark_manifest_path",
        "candidate_benchmark_manifest_path",
    }
    paths: dict[str, Path] = {}
    warnings: list[str] = []
    for target_key, raw_value in mapping.items():
        if not raw_value:
            if target_key not in optional_path_keys:
                warnings.append(f"comparison_suite_{target_key}_missing")
            continue
        path = Path(str(raw_value)).expanduser()
        if not path.is_absolute():
            path = base_dir / path
        paths[target_key] = path.resolve()
    return paths, warnings


def _roadmap_paths_from_threshold_adoption_package(
    threshold_adoption_package_path: Path | None,
) -> tuple[dict[str, Path], list[str]]:
    if threshold_adoption_package_path is None:
        return {}, []
    try:
        package = EvidenceGroundingThresholdAdoptionReviewPackage.model_validate(
            _load_json_object(threshold_adoption_package_path)
        )
        comparison_suite_package_path = _resolve_related_review_path(
            package.comparison_suite_package_path,
            base_path=threshold_adoption_package_path,
        )
        suite_package = EvidenceGroundingFixedGoldsetComparisonSuitePackage.model_validate(
            _load_json_object(comparison_suite_package_path)
        )
    except (OSError, ValueError, ValidationError, RuntimeError) as exc:
        return {}, [f"threshold_adoption_package_linkage_load_failed: {exc}"]

    paths: dict[str, Path] = {}
    warnings: list[str] = []
    for label, raw_run_package_path in (
        ("baseline", suite_package.baseline_run_package_path),
        ("candidate", suite_package.candidate_run_package_path),
    ):
        try:
            run_package_path = _resolve_related_review_path(
                raw_run_package_path,
                base_path=comparison_suite_package_path,
            )
            run_package = EvidenceGroundingBenchmarkRunPackage.model_validate(
                _load_json_object(run_package_path)
            )
            paths[f"{label}_benchmark_manifest_package_path"] = _resolve_related_review_path(
                run_package.benchmark_manifest_package_path,
                base_path=run_package_path,
            )
        except (OSError, ValueError, ValidationError, RuntimeError) as exc:
            warnings.append(f"{label}_benchmark_manifest_package_path_load_failed: {exc}")
    return paths, warnings


def _roadmap_check_gold_release_readiness(
    release_readiness_report: PaperUnderstandingGoldReleaseReadinessReport | None,
) -> EvidenceGroundingRoadmapCompletionCheck:
    if release_readiness_report is None:
        return EvidenceGroundingRoadmapCompletionCheck(
            requirement_id="fixed_goldset_release_readiness",
            requirement="Publish and review a seed/eval/holdout fixed paper-understanding goldset bundle before candidate comparison.",
            status="fail",
            evidence=["gold_release_readiness_loaded=false"],
            detail="Gold release-readiness report did not load.",
        )
    required_splits = set(release_readiness_report.required_splits)
    covered_splits = {
        summary.goldset_split
        for summary in release_readiness_report.split_summaries
        if summary.goldset_split is not None and summary.status == "pass"
    }
    required_core_splits = {"seed", "eval", "holdout"}
    missing_core_splits = sorted(required_core_splits - required_splits)
    uncovered_core_splits = sorted(required_core_splits - covered_splits)
    passed = (
        release_readiness_report.release_ready
        and not release_readiness_report.blockers
        and not missing_core_splits
        and not uncovered_core_splits
        and release_readiness_report.ready_count >= len(required_core_splits)
        and release_readiness_report.invalid_count == 0
        and not release_readiness_report.duplicate_paper_ids
    )
    return EvidenceGroundingRoadmapCompletionCheck(
        requirement_id="fixed_goldset_release_readiness",
        requirement="Publish and review a seed/eval/holdout fixed paper-understanding goldset bundle before candidate comparison.",
        status="pass" if passed else "fail",
        evidence=[
            f"release_ready={release_readiness_report.release_ready}",
            f"required_splits={','.join(release_readiness_report.required_splits) or '-'}",
            f"covered_passing_splits={','.join(sorted(covered_splits)) or '-'}",
            f"missing_core_required_splits={','.join(missing_core_splits) or '-'}",
            f"uncovered_core_splits={','.join(uncovered_core_splits) or '-'}",
            f"ready_count={release_readiness_report.ready_count}",
            f"invalid_count={release_readiness_report.invalid_count}",
            f"duplicate_paper_ids={','.join(release_readiness_report.duplicate_paper_ids) or '-'}",
            f"blockers={','.join(release_readiness_report.blockers) or '-'}",
            f"goldset_ids={','.join(release_readiness_report.goldset_ids) or '-'}",
        ],
        detail=(
            "Gold release-readiness report proves a reviewed seed/eval/holdout fixed-goldset bundle."
            if passed
            else "Missing or blocked seed/eval/holdout gold release-readiness evidence."
        ),
    )


def _roadmap_check_gold_release_package_consistency(
    release_package: PaperUnderstandingGoldReleasePackageReport,
    release_readiness_report: PaperUnderstandingGoldReleaseReadinessReport | None,
    *,
    package_path: Path | None,
    readiness_path: Path | None,
) -> EvidenceGroundingRoadmapCompletionCheck:
    evidence = [
        f"package_id={release_package.package_id}",
        f"goldset_id={release_package.goldset_id}",
        f"package_path={package_path or '-'}",
        f"readiness_path={readiness_path or '-'}",
        f"package_linked_readiness_path={release_package.release_readiness_report_path}",
    ]
    if release_readiness_report is None:
        return EvidenceGroundingRoadmapCompletionCheck(
            requirement_id="fixed_goldset_release_package_consistency",
            requirement="When a paper-understanding gold release package is supplied, its embedded readiness and linked readiness report must agree.",
            status="fail",
            evidence=evidence,
            detail="Release package was supplied, but its linked release-readiness report did not load.",
        )
    expected_path = _resolve_related_review_path(
        release_package.release_readiness_report_path,
        base_path=package_path,
    )
    path_matches = expected_path == readiness_path
    package_payload = release_package.release_readiness.model_dump(mode="json")
    linked_payload = release_readiness_report.model_dump(mode="json")
    payload_matches = package_payload == linked_payload
    package_manifest_paths = {
        str(_resolve_related_review_path(path, base_path=package_path))
        for path in release_package.manifest_paths
    }
    source_manifest_paths = {
        str(_resolve_related_review_path(item.manifest_out, base_path=package_path))
        for item in release_package.source_split_manifests
    }
    readiness_manifest_paths = {
        str(_resolve_related_review_path(summary.manifest_path, base_path=readiness_path))
        for summary in release_readiness_report.split_summaries
    }
    manifest_paths_match = package_manifest_paths == readiness_manifest_paths
    source_manifest_paths_match = not source_manifest_paths or source_manifest_paths == package_manifest_paths
    source_manifests_rebuild_current = True
    source_manifest_rebuild_errors: list[str] = []
    for source_item in release_package.source_split_manifests:
        staging_path = _resolve_related_review_path(source_item.staging_manifest_path, base_path=package_path)
        manifest_out_path = _resolve_related_review_path(source_item.manifest_out, base_path=package_path)
        try:
            current_manifest = PaperUnderstandingGoldManifest.model_validate(_load_json_object(manifest_out_path))
            rebuilt_manifest = build_paper_understanding_gold_manifest(
                [staging_path],
                goldset_id=release_package.goldset_id,
                goldset_split=source_item.goldset_split,
                manifest_path=manifest_out_path,
                require_ready=False,
            )
        except Exception as exc:
            source_manifests_rebuild_current = False
            source_manifest_rebuild_errors.append(f"{source_item.goldset_split}:{exc}")
            continue
        if _manifest_stable_fingerprint(current_manifest) != _manifest_stable_fingerprint(rebuilt_manifest):
            source_manifests_rebuild_current = False
            source_manifest_rebuild_errors.append(f"{source_item.goldset_split}:manifest_content_mismatch")
    readiness_goldset_ids = set(release_readiness_report.goldset_ids)
    goldset_id_matches = readiness_goldset_ids == {release_package.goldset_id}
    current_readiness_matches = False
    current_readiness_error = "-"
    try:
        current_readiness = build_paper_understanding_gold_release_readiness_report(
            [Path(path) for path in package_manifest_paths],
            required_splits=release_readiness_report.required_splits,
            min_ready_per_split=release_readiness_report.min_ready_per_split,
            require_single_goldset_id=True,
        )
        current_readiness_matches = _release_readiness_stable_fingerprint(
            current_readiness
        ) == _release_readiness_stable_fingerprint(release_readiness_report)
    except Exception as exc:
        current_readiness_error = str(exc)
    passed = (
        path_matches
        and payload_matches
        and manifest_paths_match
        and source_manifest_paths_match
        and source_manifests_rebuild_current
        and goldset_id_matches
        and current_readiness_matches
    )
    return EvidenceGroundingRoadmapCompletionCheck(
        requirement_id="fixed_goldset_release_package_consistency",
        requirement="When a paper-understanding gold release package is supplied, its embedded readiness and linked readiness report must agree.",
        status="pass" if passed else "fail",
        evidence=[
            *evidence,
            f"resolved_package_linked_readiness_path={expected_path}",
            f"linked_path_matches_effective_path={path_matches}",
            f"embedded_readiness_matches_linked_report={payload_matches}",
            f"package_manifest_count={len(package_manifest_paths)}",
            f"source_split_manifest_count={len(release_package.source_split_manifests)}",
            f"source_split_manifest_paths_match_package={source_manifest_paths_match}",
            f"source_split_names={','.join(item.goldset_split for item in release_package.source_split_manifests) or '-'}",
            f"source_split_manifests_rebuild_current={source_manifests_rebuild_current}",
            f"source_split_manifest_rebuild_errors={';'.join(source_manifest_rebuild_errors) or '-'}",
            f"readiness_manifest_count={len(readiness_manifest_paths)}",
            f"package_manifest_paths_match_readiness={manifest_paths_match}",
            f"readiness_goldset_ids={','.join(sorted(readiness_goldset_ids)) or '-'}",
            f"package_goldset_id_matches_readiness={goldset_id_matches}",
            f"current_manifests_match_linked_readiness={current_readiness_matches}",
            f"current_manifest_readiness_error={current_readiness_error}",
            f"embedded_release_ready={release_package.release_readiness.release_ready}",
            f"linked_release_ready={release_readiness_report.release_ready}",
        ],
        detail=(
            "Release package and linked release-readiness report are consistent."
            if passed
            else "Release package and linked release-readiness report disagree or point to different files."
        ),
    )


def _manifest_stable_fingerprint(report: PaperUnderstandingGoldManifest) -> dict[str, Any]:
    return {
        "goldset_id": report.goldset_id,
        "goldset_split": report.goldset_split,
        "items": [item.model_dump(mode="json") for item in report.items],
    }


def _release_readiness_stable_fingerprint(report: PaperUnderstandingGoldReleaseReadinessReport) -> dict[str, Any]:
    return {
        "required_splits": list(report.required_splits),
        "min_ready_per_split": report.min_ready_per_split,
        "manifest_count": report.manifest_count,
        "goldset_ids": list(report.goldset_ids),
        "item_count": report.item_count,
        "ready_count": report.ready_count,
        "invalid_count": report.invalid_count,
        "missing_splits": list(report.missing_splits),
        "underfilled_splits": list(report.underfilled_splits),
        "duplicate_paper_ids": list(report.duplicate_paper_ids),
        "blockers": list(report.blockers),
        "release_ready": report.release_ready,
        "split_summaries": sorted(
            [
            {
                "manifest_path": str(_resolve_related_review_path(summary.manifest_path, base_path=None)),
                "goldset_id": summary.goldset_id,
                "goldset_split": summary.goldset_split,
                "item_count": summary.item_count,
                "ready_count": summary.ready_count,
                "warn_count": summary.warn_count,
                "fail_count": summary.fail_count,
                "invalid_count": summary.invalid_count,
                "paper_ids": list(summary.paper_ids),
                "status": summary.status,
            }
            for summary in report.split_summaries
            ],
            key=lambda item: (str(item["goldset_split"] or ""), str(item["manifest_path"])),
        ),
    }


def _roadmap_check_fixed_goldset_run(
    candidate_benchmark: EvidenceGroundingBenchmarkReport | None,
    run_readiness_report: EvidenceGroundingFixedGoldsetRunReadinessReport | None,
    *,
    comparison_suite_path: Path | None,
    suite_paths: dict[str, Path],
    effective_paths: dict[str, Path | None],
    gold_release_package: PaperUnderstandingGoldReleasePackageReport | None = None,
    gold_release_package_path: Path | None = None,
    run_root: Path | None = None,
) -> EvidenceGroundingRoadmapCompletionCheck:
    evidence: list[str] = []
    suite_ok = False
    comparison_suite_consistency_findings: list[str] = []
    suite_missing_paths: list[str] = []
    suite_mismatched_paths: list[str] = []
    required_suite_paths = (
        "baseline_benchmark_report_path",
        "candidate_benchmark_report_path",
        "comparison_report_path",
        "run_readiness_report_path",
    )
    if comparison_suite_path is None:
        evidence.append("comparison_suite_path=-")
    else:
        try:
            suite_payload = _load_json_object(comparison_suite_path)
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            evidence.extend([f"comparison_suite_path={comparison_suite_path}", f"comparison_suite_load_error={exc}"])
        else:
            suite_schema_ok = suite_payload.get("schema_version") == "evidence_grounding_fixed_goldset_comparison_suite.v1"
            suite_layer_ok = suite_payload.get("layer") == "review_gate_artifact"
            suite_canonical_ok = suite_payload.get("canonical_status") == "non_canonical"
            suite_ok = suite_schema_ok and suite_layer_ok and suite_canonical_ok
            comparison_suite_consistency_findings = _fixed_goldset_comparison_suite_readiness_findings(
                suite_payload,
                base_path=comparison_suite_path,
            )
            evidence.extend(
                [
                    f"comparison_suite_path={comparison_suite_path}",
                    f"comparison_suite_schema_ok={suite_schema_ok}",
                    f"comparison_suite_layer_ok={suite_layer_ok}",
                    f"comparison_suite_canonical_ok={suite_canonical_ok}",
                    f"comparison_suite_consistency_findings={','.join(comparison_suite_consistency_findings) or '-'}",
                ]
            )
    for key in required_suite_paths:
        suite_path = suite_paths.get(key)
        effective_path = effective_paths.get(key)
        if suite_path is None:
            suite_missing_paths.append(key)
            continue
        if effective_path is None or suite_path != effective_path:
            suite_mismatched_paths.append(key)
    evidence.extend(
        [
            f"comparison_suite_missing_paths={','.join(suite_missing_paths) or '-'}",
            f"comparison_suite_mismatched_paths={','.join(suite_mismatched_paths) or '-'}",
        ]
    )
    if gold_release_package is not None:
        release_paper_ids = _roadmap_release_package_paper_ids(gold_release_package)
        release_package_display = (
            mask_local_path(str(gold_release_package_path)) or str(gold_release_package_path)
            if gold_release_package_path is not None
            else "-"
        )
        evidence.extend(
            [
                f"gold_release_package_path={release_package_display}",
                f"gold_release_package_item_count={len(release_paper_ids)}",
                f"gold_release_package_paper_ids_sample={','.join(release_paper_ids[:5]) or '-'}"
                + (f",...{len(release_paper_ids) - 5}_more" if len(release_paper_ids) > 5 else ""),
            ]
        )
        if run_root is not None:
            missing_paper_dirs = [
                paper_id for paper_id in release_paper_ids if not (Path(run_root) / paper_id).exists()
            ]
            alternate_run_dir_candidates = {
                paper_id: _discover_alternate_release_package_run_dirs(
                    run_root=Path(run_root),
                    paper_id=paper_id,
                    required_artifacts=[],
                )
                for paper_id in missing_paper_dirs
            }
            alternate_run_dir_candidates = {
                paper_id: candidates
                for paper_id, candidates in alternate_run_dir_candidates.items()
                if candidates
            }
            evidence.extend(
                [
                    f"gold_release_package_run_root={mask_local_path(str(run_root)) or str(run_root)}",
                    "gold_release_package_run_root_existing_paper_dir_count="
                    f"{len(release_paper_ids) - len(missing_paper_dirs)}",
                    "gold_release_package_run_root_missing_paper_dir_count="
                    f"{len(missing_paper_dirs)}",
                    "gold_release_package_run_root_missing_paper_ids="
                    f"{','.join(missing_paper_dirs) or '-'}",
                    "gold_release_package_run_root_candidate_alternate_run_dir_count="
                    f"{sum(len(candidates) for candidates in alternate_run_dir_candidates.values())}",
                    "gold_release_package_run_root_candidate_alternate_paper_ids="
                    f"{','.join(sorted(alternate_run_dir_candidates)) or '-'}",
                ]
            )
    if run_readiness_report is not None:
        run_readiness_consistency_findings = _fixed_goldset_run_readiness_artifact_findings(
            run_readiness_report.model_dump(mode="json")
        )
        run_readiness_scorecard_input_evidence = _fixed_goldset_run_readiness_scorecard_input_evidence(
            run_readiness_report
        )
        evidence.extend(
            [
                f"comparison_run_ready={run_readiness_report.comparison_run_ready}",
                f"run_readiness_goldset_id={run_readiness_report.goldset_id or '-'}",
                f"run_readiness_goldset_split={run_readiness_report.goldset_split or '-'}",
                f"goldset_item_count={run_readiness_report.goldset_item_count}",
                f"fail_count={run_readiness_report.fail_count}",
                f"run_readiness_consistency_findings={','.join(run_readiness_consistency_findings) or '-'}",
                *run_readiness_scorecard_input_evidence,
            ]
        )
    else:
        run_readiness_consistency_findings = []
    if candidate_benchmark is not None:
        evidence.extend(
            [
                f"candidate_goldset_id={candidate_benchmark.goldset_id or '-'}",
                f"candidate_goldset_split={candidate_benchmark.goldset_split or '-'}",
                f"candidate_item_count={candidate_benchmark.item_count}",
                f"candidate_goldset_item_count={candidate_benchmark.goldset_item_count}",
                f"candidate_goldset_covered_paper_count={candidate_benchmark.goldset_covered_paper_count}",
                f"candidate_goldset_readiness_fail_count={candidate_benchmark.goldset_readiness_fail_count}",
                f"candidate_goldset_missing_paper_ids={','.join(candidate_benchmark.goldset_missing_paper_ids) or '-'}",
                f"candidate_goldset_not_ready_paper_ids={','.join(candidate_benchmark.goldset_not_ready_paper_ids) or '-'}",
            ]
        )
    goldset_matches = (
        run_readiness_report is not None
        and candidate_benchmark is not None
        and candidate_benchmark.goldset_id == run_readiness_report.goldset_id
        and candidate_benchmark.goldset_split == run_readiness_report.goldset_split
        and candidate_benchmark.goldset_item_count == run_readiness_report.goldset_item_count
    )
    passed = (
        suite_ok
        and not comparison_suite_consistency_findings
        and not suite_missing_paths
        and not suite_mismatched_paths
        and run_readiness_report is not None
        and run_readiness_report.comparison_run_ready
        and not run_readiness_consistency_findings
        and run_readiness_report.goldset_item_count > 0
        and candidate_benchmark is not None
        and bool(candidate_benchmark.goldset_id)
        and bool(candidate_benchmark.goldset_split)
        and candidate_benchmark.item_count > 0
        and candidate_benchmark.goldset_item_count is not None
        and candidate_benchmark.goldset_covered_paper_count == candidate_benchmark.goldset_item_count
        and candidate_benchmark.goldset_readiness_fail_count == 0
        and goldset_matches
        and not candidate_benchmark.goldset_missing_paper_ids
        and not candidate_benchmark.goldset_extra_paper_ids
        and not candidate_benchmark.goldset_not_ready_paper_ids
    )
    return EvidenceGroundingRoadmapCompletionCheck(
        requirement_id="fixed_goldset_candidate_run",
        requirement="Run a fixed paper-understanding goldset through a candidate parser/model/prompt configuration.",
        status="pass" if passed else "fail",
        evidence=evidence,
        detail=(
            "A loadable fixed-goldset comparison suite, run-readiness report, and candidate benchmark coverage prove the candidate was evaluated on the declared fixed target."
            if passed
            else "Missing, mismatched, or incomplete fixed-goldset suite/run-readiness/candidate benchmark evidence."
        ),
    )


def _roadmap_release_package_paper_ids(
    release_package: PaperUnderstandingGoldReleasePackageReport,
) -> list[str]:
    paper_ids: list[str] = []
    for summary in release_package.release_readiness.split_summaries:
        paper_ids.extend(str(paper_id).strip() for paper_id in summary.paper_ids if str(paper_id).strip())
    return _dedupe_strings_preserving_order(paper_ids)


def _fixed_goldset_run_readiness_scorecard_input_evidence(
    run_readiness_report: EvidenceGroundingFixedGoldsetRunReadinessReport,
) -> list[str]:
    missing_required_names: set[str] = set()
    malformed_required_names: set[str] = set()
    missing_core_names: set[str] = set()
    items_missing_any_core = 0
    items_missing_all_core = 0
    for lane_summary in run_readiness_report.lane_summaries:
        for item in lane_summary.items:
            present_artifacts = set(item.present_required_artifacts) | set(item.present_optional_artifacts)
            missing_core = sorted(set(CORE_SCORECARD_INPUT_ARTIFACTS) - present_artifacts)
            if missing_core:
                items_missing_any_core += 1
                missing_core_names.update(missing_core)
            if len(missing_core) == len(CORE_SCORECARD_INPUT_ARTIFACTS):
                items_missing_all_core += 1
            missing_required_names.update(item.missing_required_artifacts)
            malformed_required_names.update(item.malformed_required_artifacts)
    return [
        f"run_readiness_missing_required_artifact_names={','.join(sorted(missing_required_names)) or '-'}",
        f"run_readiness_malformed_required_artifact_names={','.join(sorted(malformed_required_names)) or '-'}",
        f"run_readiness_missing_core_scorecard_input_names={','.join(sorted(missing_core_names)) or '-'}",
        f"run_readiness_items_missing_any_core_scorecard_inputs={items_missing_any_core}",
        f"run_readiness_items_missing_all_core_scorecard_inputs={items_missing_all_core}",
    ]


def _roadmap_check_candidate_configuration_lineage(
    candidate_benchmark: EvidenceGroundingBenchmarkReport | None,
    *,
    candidate_benchmark_manifest_path: Path | None = None,
    candidate_benchmark_manifest_package_path: Path | None = None,
    gold_release_package_path: Path | None = None,
    candidate_lineage_run_dir_map_path: Path | None = None,
    candidate_lineage_run_dir_map_discovery_path: Path | None = None,
    candidate_lineage_patch_template_path: Path | None = None,
    candidate_lineage_prefilled_patch_template_path: Path | None = None,
    candidate_lineage_patch_template_fill_readiness_path: Path | None = None,
    candidate_lineage_patch_template_fill_task_export_path: Path | None = None,
    candidate_lineage_patch_template_fill_review_status_path: Path | None = None,
) -> EvidenceGroundingRoadmapCompletionCheck:
    review_status = _patch_template_fill_review_status_summary(
        candidate_lineage_patch_template_fill_review_status_path
    )
    candidate_lineage_fill_task_export_path = (
        review_status.get("source_task_export_path")
        or candidate_lineage_patch_template_fill_task_export_path
        or "-"
    )
    candidate_lineage_prefilled_patch_template_path_evidence = (
        candidate_lineage_prefilled_patch_template_path
        or _prefilled_patch_template_path_from_review_status_source(review_status)
        or "-"
    )
    path_evidence = [
        f"candidate_benchmark_manifest_path={candidate_benchmark_manifest_path or '-'}",
        f"candidate_benchmark_manifest_package_path={candidate_benchmark_manifest_package_path or '-'}",
        f"gold_release_package_path={gold_release_package_path or '-'}",
        f"candidate_lineage_run_dir_map_path={candidate_lineage_run_dir_map_path or '-'}",
        *_candidate_lineage_run_dir_map_source_evidence(candidate_lineage_run_dir_map_path),
        *_candidate_lineage_run_dir_map_discovery_evidence(
            candidate_lineage_run_dir_map_discovery_path,
            run_dir_map_path=candidate_lineage_run_dir_map_path,
        ),
        f"candidate_lineage_patch_template_path={candidate_lineage_patch_template_path or '-'}",
        "candidate_lineage_prefilled_patch_template_path="
        f"{candidate_lineage_prefilled_patch_template_path_evidence}",
        "candidate_lineage_patch_template_fill_readiness_path="
        f"{candidate_lineage_patch_template_fill_readiness_path or '-'}",
        "candidate_lineage_patch_template_fill_task_export_path="
        f"{candidate_lineage_fill_task_export_path}",
        "candidate_lineage_patch_template_fill_review_status_path="
        f"{candidate_lineage_patch_template_fill_review_status_path or '-'}",
        "candidate_lineage_patch_template_fill_review_status_ready_for_apply="
        f"{review_status.get('ready_for_apply', '-')}",
        "candidate_lineage_patch_template_fill_review_status_missing_value_count="
        f"{review_status.get('missing_value_count', '-')}",
        "candidate_lineage_patch_template_fill_review_status_missing_value_count_by_field="
        f"{review_status.get('missing_value_count_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_missing_evidence_count="
        f"{review_status.get('missing_evidence_count', '-')}",
        "candidate_lineage_patch_template_fill_review_status_missing_evidence_count_by_field="
        f"{review_status.get('missing_evidence_count_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_suggested_value_count_by_field="
        f"{review_status.get('suggested_value_count_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_missing_suggestion_count_by_field="
        f"{review_status.get('missing_suggestion_count_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_missing_suggestion_task_ids_by_field="
        f"{review_status.get('missing_suggestion_task_ids_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_available_context_count_by_field="
        f"{review_status.get('available_context_count_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_available_context_keys_by_field="
        f"{review_status.get('available_context_keys_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_available_context_values_by_field="
        f"{review_status.get('available_context_values_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_missing_context_count_by_field="
        f"{review_status.get('missing_context_count_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_missing_context_task_ids_by_field="
        f"{review_status.get('missing_context_task_ids_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_fail_count="
        f"{review_status.get('fail_count', '-')}",
        "candidate_lineage_patch_template_fill_review_status_fail_count_by_field="
        f"{review_status.get('fail_count_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_record_count="
        f"{review_status.get('open_record_count', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_record_refs="
        f"{review_status.get('open_record_refs', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_field_names_by_record_ref="
        f"{review_status.get('open_field_names_by_record_ref', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_task_ids="
        f"{review_status.get('open_task_ids', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_task_ids_by_field="
        f"{review_status.get('open_task_ids_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_task_ids_by_record_ref="
        f"{review_status.get('open_task_ids_by_record_ref', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_record_filled_patch_field_counts_by_field="
        f"{review_status.get('open_record_filled_patch_field_counts_by_field', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_record_filled_patch_fields_by_record_ref="
        f"{review_status.get('open_record_filled_patch_fields_by_record_ref', '-')}",
        "candidate_lineage_patch_template_fill_review_status_reviewed_csv_path="
        f"{review_status.get('reviewed_csv_path', '-')}",
        "candidate_lineage_patch_template_fill_review_status_annotated_csv_path="
        f"{review_status.get('annotated_csv_path', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_csv_path="
        f"{review_status.get('open_csv_path', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_record_csv_path="
        f"{review_status.get('open_record_csv_path', '-')}",
        "candidate_lineage_patch_template_fill_review_status_open_csv_row_count="
        f"{review_status.get('open_csv_row_count', '-')}",
    ]
    if candidate_benchmark is None:
        return EvidenceGroundingRoadmapCompletionCheck(
            requirement_id="candidate_configuration_lineage",
            requirement="Record parser/model/prompt/profile configuration lineage for the evaluated candidate.",
            status="fail",
            evidence=[*path_evidence, "candidate_benchmark_loaded=false"],
            detail="Candidate benchmark report did not load.",
        )
    candidate_config_count = len(candidate_benchmark.candidate_configs)
    unconfigured_items = [
        item.candidate_id
        for item in candidate_benchmark.scorecards
        if item.candidate_config is None or not item.candidate_config.has_complete_replay_lineage()
    ]
    passed = candidate_config_count > 0 and not unconfigured_items
    evidence = [
        *path_evidence,
        f"candidate_config_count={candidate_config_count}",
        f"unconfigured_candidate_ids={','.join(unconfigured_items) or '-'}",
    ]
    if unconfigured_items:
        evidence.extend(_candidate_configuration_lineage_diagnostic_evidence(candidate_benchmark.scorecards))
    return EvidenceGroundingRoadmapCompletionCheck(
        requirement_id="candidate_configuration_lineage",
        requirement="Record parser/model/prompt/profile configuration lineage for the evaluated candidate.",
        status="pass" if passed else "fail",
        evidence=evidence,
        detail=(
            "Candidate benchmark includes typed lineage for every scored item."
            if passed
            else "Candidate benchmark is missing typed parser/model/prompt/profile lineage for one or more scored items."
        ),
    )


def _candidate_configuration_lineage_diagnostic_evidence(
    scorecard_items: list[EvidenceGroundingBenchmarkScorecardItem],
) -> list[str]:
    missing_fields: list[str] = []
    available_context: list[str] = []
    for item in scorecard_items:
        if item.candidate_config is not None and item.candidate_config.has_complete_replay_lineage():
            continue
        candidate_id = str(item.candidate_id or "").strip() or "unknown"
        missing = _candidate_config_missing_replay_fields(item.candidate_config)
        if missing:
            missing_fields.append(f"{candidate_id}:{','.join(missing)}")
        context = _candidate_config_available_replay_context(item)
        if context:
            formatted_context = ",".join(f"{key}={value}" for key, value in context.items())
            available_context.append(f"{candidate_id}:{formatted_context}")
    return [
        f"candidate_config_missing_replay_fields={';'.join(missing_fields) or '-'}",
        f"candidate_config_available_replay_context={';'.join(available_context) or '-'}",
    ]


def _candidate_config_missing_replay_fields(
    candidate_config: EvidenceGroundingCandidateConfig | None,
) -> list[str]:
    return [
        field_name
        for field_name in CANDIDATE_CONFIG_REPLAY_LINEAGE_FIELDS
        if candidate_config is None or not getattr(candidate_config, field_name)
    ]


def _candidate_config_available_replay_context(
    item: EvidenceGroundingBenchmarkScorecardItem,
) -> dict[str, str]:
    return _candidate_config_available_replay_context_from_values(
        item.candidate_config,
        run_dir=Path(str(item.run_dir or "")).expanduser(),
    )


def _candidate_config_available_replay_context_from_values(
    candidate_config: EvidenceGroundingCandidateConfig | None,
    *,
    run_dir: Path,
) -> dict[str, str]:
    out: dict[str, str] = {}
    if candidate_config is not None:
        for field_name in CANDIDATE_CONFIG_REPLAY_LINEAGE_FIELDS:
            _add_candidate_config_context_value(out, f"candidate_config.{field_name}", getattr(candidate_config, field_name))

    run_dir = Path(run_dir).expanduser()
    run_meta = _load_optional_json_object(run_dir / "run_meta.json")
    bootstrap_meta = _load_optional_json_object(run_dir / "bootstrap_meta.json")
    if run_meta:
        for field_name in CANDIDATE_CONFIG_REPLAY_LINEAGE_FIELDS:
            _add_candidate_config_context_value(out, f"run_meta.{field_name}", run_meta.get(field_name))
        for key in (
            "parser_backend",
            "requested_parser_backend",
            "selected_backend",
            "profile_id",
            "persona_id",
            "config_snapshot",
            "prompts_snapshot",
        ):
            _add_candidate_config_context_value(out, f"run_meta.{key}", run_meta.get(key))
        _add_candidate_config_context_value(
            out,
            "run_meta.config_snapshot_ref",
            _snapshot_file_ref(run_meta.get("config_snapshot")),
        )
        _add_candidate_config_context_value(
            out,
            "run_meta.prompts_snapshot_ref",
            _snapshot_file_ref(run_meta.get("prompts_snapshot")),
        )
        models_used = run_meta.get("models_used")
        if isinstance(models_used, dict):
            _add_candidate_config_context_value(out, "run_meta.models_used.reader", models_used.get("reader"))
        reader_analysis = run_meta.get("reader_analysis")
        if isinstance(reader_analysis, dict):
            _add_candidate_config_context_value(out, "run_meta.reader_analysis.model_name", reader_analysis.get("model_name"))
        lanes = run_meta.get("inference_lanes")
        if isinstance(lanes, dict):
            for lane_name in sorted(lanes):
                lane = lanes.get(lane_name)
                if not isinstance(lane, dict):
                    continue
                prefix = f"run_meta.inference_lanes.{lane_name}"
                for key in ("selected_backend", "provider_name", "provider_model"):
                    _add_candidate_config_context_value(out, f"{prefix}.{key}", lane.get(key))
        llm_params = run_meta.get("llm_params")
        if isinstance(llm_params, dict):
            for key in ("mode", "provider_local", "provider_cloud"):
                _add_candidate_config_context_value(out, f"run_meta.llm_params.{key}", llm_params.get(key))
    if bootstrap_meta:
        for key in (
            "parser_backend",
            "requested_parser_backend",
            "reader_model",
            "profile_id",
            "persona_id",
        ):
            _add_candidate_config_context_value(out, f"bootstrap_meta.{key}", bootstrap_meta.get(key))
    return dict(sorted(out.items()))


def _candidate_lineage_suggestions_from_context(
    candidate_config: EvidenceGroundingCandidateConfig | None,
    *,
    missing_fields: list[str],
    context: Mapping[str, str],
) -> dict[str, str]:
    suggestions: dict[str, str] = {}
    for field_name in missing_fields:
        value = str(getattr(candidate_config, field_name, "") or "").strip() if candidate_config is not None else ""
        if value:
            suggestions[field_name] = value
    missing = set(missing_fields) - set(suggestions)
    if "llm_provider" in missing:
        provider = _candidate_lineage_single_context_value(
            context,
            suffixes=(".provider_name",),
        )
        if provider:
            suggestions["llm_provider"] = provider
        else:
            selected_backend = context.get("run_meta.selected_backend") or context.get(
                "run_meta.inference_lanes.reader.selected_backend"
            )
            if selected_backend == "local":
                provider = context.get("run_meta.llm_params.provider_local")
            elif selected_backend in {"cloud", "commercial"}:
                provider = context.get("run_meta.llm_params.provider_cloud")
            else:
                provider = ""
            if provider:
                suggestions["llm_provider"] = provider
    if "llm_model" in missing:
        model = _candidate_lineage_single_context_value(
            context,
            suffixes=(
                ".provider_model",
                ".reader",
                ".model_name",
                ".reader_model",
            ),
        )
        if model:
            suggestions["llm_model"] = model
    if "llm_model_version" in missing:
        model_version = _candidate_lineage_single_context_value(
            context,
            suffixes=(
                ".model_version",
                ".llm_model_version",
            ),
        )
        if model_version:
            suggestions["llm_model_version"] = model_version
    if "reader_profile_version" in missing and context.get("run_meta.reader_profile_version"):
        suggestions["reader_profile_version"] = context["run_meta.reader_profile_version"]
    if "prompt_version" in missing and context.get("run_meta.prompts_snapshot_ref"):
        suggestions["prompt_version"] = context["run_meta.prompts_snapshot_ref"]
    return suggestions


def _snapshot_file_ref(raw_path: Any) -> str:
    text = str(raw_path or "").strip()
    if not text:
        return ""
    path = Path(text).expanduser()
    try:
        digest = hashlib.sha256(path.read_bytes()).hexdigest()[:16]
    except Exception:
        return ""
    return f"{path.name}@sha256:{digest}"


def _candidate_lineage_single_context_value(
    context: Mapping[str, str],
    *,
    suffixes: tuple[str, ...],
) -> str:
    values: list[str] = []
    seen: set[str] = set()
    for key, value in sorted(context.items()):
        if not any(key.endswith(suffix) for suffix in suffixes):
            continue
        text = str(value or "").strip()
        if not text or text in seen:
            continue
        seen.add(text)
        values.append(text)
    return values[0] if len(values) == 1 else ""


def _load_optional_json_object(path: Path) -> dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return payload if isinstance(payload, dict) else {}


def _add_candidate_config_context_value(out: dict[str, str], key: str, value: Any) -> None:
    text = str(value or "").strip()
    if not text:
        return
    masked = mask_local_path(text) or text
    out[key] = masked


def _roadmap_check_scorecards(
    baseline_benchmark: EvidenceGroundingBenchmarkReport | None,
    candidate_benchmark: EvidenceGroundingBenchmarkReport | None,
    *,
    baseline_benchmark_manifest_path: Path | None = None,
    candidate_benchmark_manifest_path: Path | None = None,
    baseline_benchmark_manifest_package_path: Path | None = None,
    candidate_benchmark_manifest_package_path: Path | None = None,
) -> EvidenceGroundingRoadmapCompletionCheck:
    evidence: list[str] = [
        f"baseline_benchmark_manifest_path={baseline_benchmark_manifest_path or '-'}",
        f"candidate_benchmark_manifest_path={candidate_benchmark_manifest_path or '-'}",
        f"baseline_benchmark_manifest_package_path={baseline_benchmark_manifest_package_path or '-'}",
        f"candidate_benchmark_manifest_package_path={candidate_benchmark_manifest_package_path or '-'}",
    ]
    for label, report in (("baseline", baseline_benchmark), ("candidate", candidate_benchmark)):
        if report is None:
            evidence.append(f"{label}_benchmark_loaded=false")
            continue
        readiness_fields_present = _benchmark_scorecard_readiness_fields_present(report)
        malformed_input_metric = report.aggregate_runtime_proxy_metrics.get("malformed_input_artifact_count")
        malformed_input_metric_available = _is_available_number(malformed_input_metric)
        malformed_input_metric_value = (
            str(malformed_input_metric.value) if malformed_input_metric_available else "-"
        )
        evidence.extend(
            [
                f"{label}_item_count={report.item_count}",
                f"{label}_scorecard_count={len(report.scorecards)}",
                f"{label}_scorecard_readiness_fields_present={readiness_fields_present}",
                f"{label}_scorecard_readiness_fail_count={report.scorecard_readiness_fail_count}",
                f"{label}_scorecard_fail_candidate_ids={_scorecard_fail_candidate_ids(report)}",
                f"{label}_scorecard_fail_reason_codes={_scorecard_reason_code_summary(report, readiness_statuses={'fail'})}",
                f"{label}_scorecard_not_ready_candidate_ids={','.join(report.scorecard_not_ready_candidate_ids) or '-'}",
                f"{label}_scorecard_not_ready_reason_codes={_scorecard_reason_code_summary(report, readiness_statuses={'warn', 'fail'})}",
                f"{label}_scorecard_fail_proxy_metrics={_scorecard_proxy_metric_summary(report, readiness_statuses={'fail'})}",
                f"{label}_scorecard_fail_repair_targets={_scorecard_repair_target_summary(report, readiness_statuses={'fail'})}",
                f"{label}_scorecard_not_ready_proxy_metrics={_scorecard_not_ready_proxy_metric_summary(report)}",
                f"{label}_scorecard_not_ready_repair_targets={_scorecard_not_ready_repair_target_summary(report)}",
                f"{label}_scorecard_first_not_ready_proxy_metrics={_scorecard_first_not_ready_proxy_metric_summary(report)}",
                f"{label}_aggregate_runtime_metric_count={len(report.aggregate_runtime_proxy_metrics)}",
                f"{label}_malformed_input_metric_available={malformed_input_metric_available}",
                f"{label}_malformed_input_artifact_count={malformed_input_metric_value}",
                f"{label}_aggregate_gold_metric_count={len(report.aggregate_gold_scored_metrics)}",
            ]
        )
    passed = (
        baseline_benchmark is not None
        and candidate_benchmark is not None
        and baseline_benchmark.item_count > 0
        and candidate_benchmark.item_count > 0
        and len(baseline_benchmark.scorecards) == baseline_benchmark.item_count
        and len(candidate_benchmark.scorecards) == candidate_benchmark.item_count
        and _benchmark_scorecard_readiness_fields_present(baseline_benchmark)
        and _benchmark_scorecard_readiness_fields_present(candidate_benchmark)
        and baseline_benchmark.scorecard_readiness_fail_count == 0
        and candidate_benchmark.scorecard_readiness_fail_count == 0
        and bool(candidate_benchmark.aggregate_runtime_proxy_metrics)
        and _benchmark_malformed_input_metric_available(baseline_benchmark)
        and _benchmark_malformed_input_metric_available(candidate_benchmark)
        and bool(candidate_benchmark.aggregate_gold_scored_metrics)
    )
    return EvidenceGroundingRoadmapCompletionCheck(
        requirement_id="per_run_and_aggregate_scorecards",
        requirement="Generate per-run and aggregate evidence-grounding scorecards.",
        status="pass" if passed else "fail",
        evidence=evidence,
        detail=(
            "Both benchmark reports include per-run scorecards and aggregate metric groups."
            if passed
            else (
                "Benchmark evidence does not prove both per-run scorecards and aggregate metrics are present, "
                "scorecard readiness fields are missing, malformed input health is not aggregated, "
                "or at least one embedded scorecard failed readiness."
            )
        ),
    )


def _benchmark_scorecard_readiness_fields_present(report: EvidenceGroundingBenchmarkReport) -> bool:
    fields_set = getattr(report, "model_fields_set", set())
    return {
        "scorecard_readiness_pass_count",
        "scorecard_readiness_warn_count",
        "scorecard_readiness_fail_count",
        "scorecard_not_ready_candidate_ids",
    } <= set(fields_set)


def _scorecard_reason_code_summary(
    report: EvidenceGroundingBenchmarkReport,
    *,
    readiness_statuses: set[str],
) -> str:
    non_blocking_reason_codes = {"gold_metrics_scored", "reviewed_eval_fixture_metrics_scored"}
    counts: dict[str, int] = {}
    for item in report.scorecards:
        if item.scorecard.readiness_status not in readiness_statuses:
            continue
        for code in item.scorecard.reason_codes:
            if code in non_blocking_reason_codes:
                continue
            counts[code] = counts.get(code, 0) + 1
    if not counts:
        return "-"
    return ",".join(f"{code}:{count}" for code, count in sorted(counts.items()))


def _scorecard_not_ready_reason_code_summary(report: EvidenceGroundingBenchmarkReport) -> str:
    return _scorecard_reason_code_summary(report, readiness_statuses={"warn", "fail"})


def _scorecard_fail_candidate_ids(
    report: EvidenceGroundingBenchmarkReport,
    *,
    candidate_id_prefix: str = "",
) -> str:
    ids = sorted(
        f"{candidate_id_prefix}{item.candidate_id}"
        for item in report.scorecards
        if item.scorecard.readiness_status == "fail" and str(item.candidate_id or "").strip()
    )
    return ",".join(ids) or "-"


def _scorecard_first_not_ready_proxy_metric_summary(report: EvidenceGroundingBenchmarkReport) -> str:
    summary = _scorecard_not_ready_proxy_metric_summary(report)
    if not summary or summary == "-":
        return "-"
    return summary.split(";", 1)[0]


def _scorecard_not_ready_proxy_metric_summary(
    report: EvidenceGroundingBenchmarkReport,
    *,
    candidate_id_prefix: str = "",
) -> str:
    return _scorecard_proxy_metric_summary(
        report,
        readiness_statuses={"warn", "fail"},
        candidate_id_prefix=candidate_id_prefix,
    )


def _scorecard_not_ready_repair_target_summary(
    report: EvidenceGroundingBenchmarkReport,
    *,
    candidate_id_prefix: str = "",
) -> str:
    return _scorecard_repair_target_summary(
        report,
        readiness_statuses={"warn", "fail"},
        candidate_id_prefix=candidate_id_prefix,
    )


def _scorecard_repair_target_summary(
    report: EvidenceGroundingBenchmarkReport,
    *,
    readiness_statuses: set[str],
    candidate_id_prefix: str = "",
) -> str:
    summaries: list[str] = []
    for item in report.scorecards:
        if item.scorecard.readiness_status not in readiness_statuses or not item.scorecard.repair_targets:
            continue
        targets = _scorecard_repair_target_list_detail(item.scorecard.repair_targets)
        if targets == "-":
            continue
        summaries.append(f"candidate_id:{candidate_id_prefix}{item.candidate_id},repair_targets:{targets}")
    return ";".join(summaries) or "-"


def _scorecard_repair_target_list_detail(targets: list[Any]) -> str:
    parts: list[str] = []
    for target in targets[:5]:
        claim_id = str(getattr(target, "claim_id", "") or "").strip()
        span_index = getattr(target, "span_index", None)
        resolution = str(getattr(target, "resolution", "") or "UNKNOWN").strip() or "UNKNOWN"
        if not claim_id or not isinstance(span_index, int):
            continue
        parts.append(f"{claim_id}#{span_index}:{resolution}")
    if len(targets) > len(parts):
        parts.append(f"...{len(targets) - len(parts)}_more")
    return ",".join(parts) if parts else "-"


def _scorecard_warning_summary(
    report: EvidenceGroundingBenchmarkReport,
    *,
    readiness_statuses: set[str],
    candidate_id_prefix: str = "",
) -> str:
    summaries: list[str] = []
    for item in report.scorecards:
        if item.scorecard.readiness_status not in readiness_statuses:
            continue
        warnings = [
            warning
            for warning in item.scorecard.warnings
            if warning.startswith("input sidecar ")
        ]
        if not warnings:
            continue
        warning_detail = "|".join(warnings[:3])
        if len(warnings) > 3:
            warning_detail += f"|...{len(warnings) - 3}_more"
        summaries.append(f"candidate_id:{candidate_id_prefix}{item.candidate_id},warnings:{warning_detail}")
    return ";".join(summaries) or "-"


def _scorecard_proxy_metric_summary(
    report: EvidenceGroundingBenchmarkReport,
    *,
    readiness_statuses: set[str],
    candidate_id_prefix: str = "",
) -> str:
    metric_names = (
        "grounded_evidence_ratio",
        "page_coverage_ratio",
        "missing_topic_signal_count",
        "duplicate_cluster_count",
        "low_overlap_claim_rate",
        "grounded_extraction_ref_rate",
    )
    summaries: list[str] = []
    for item in report.scorecards:
        if item.scorecard.readiness_status not in readiness_statuses:
            continue
        parts = [f"candidate_id:{candidate_id_prefix}{item.candidate_id}"]
        for metric_name in metric_names:
            metric = getattr(item.scorecard.runtime_proxy_metrics, metric_name, None)
            if not _is_available_number(metric):
                continue
            parts.append(f"{metric_name}:{metric.value:g}")
        summaries.append(",".join(parts))
    return ";".join(summaries) or "-"


def _benchmark_malformed_input_metric_available(report: EvidenceGroundingBenchmarkReport) -> bool:
    return _is_available_number(report.aggregate_runtime_proxy_metrics.get("malformed_input_artifact_count"))


def _roadmap_check_p0_metrics(
    candidate_benchmark: EvidenceGroundingBenchmarkReport | None,
    *,
    candidate_benchmark_manifest_path: Path | None = None,
    candidate_benchmark_manifest_package_path: Path | None = None,
    gold_release_package_path: Path | None = None,
    claim_evidence_eval_candidate_export_path: Path | None = None,
    claim_evidence_eval_candidate_export_source_correction_log_path: str | None = None,
    claim_evidence_reviewed_eval_fixtures_path: Path | None = None,
    claim_evidence_eval_review_queue_evidence: list[str] | None = None,
    p0_overstatement_review_summary_path: Path | None = None,
    p0_overstatement_review_summary: EvidenceGroundingP0OverstatementReviewSummary | None = None,
) -> EvidenceGroundingRoadmapCompletionCheck:
    reviewed_fixture_source_dir = (
        _structured_correction_evidence_source_reviewed_dir(claim_evidence_reviewed_eval_fixtures_path)
        if claim_evidence_reviewed_eval_fixtures_path is not None
        else ""
    )
    export_source_log_path = (
        claim_evidence_eval_candidate_export_source_correction_log_path
        or (
            _structured_correction_evidence_source_correction_log_path(claim_evidence_eval_candidate_export_path)
            if claim_evidence_eval_candidate_export_path is not None
            else ""
        )
    )
    evidence = [
        f"candidate_benchmark_manifest_path={candidate_benchmark_manifest_path or '-'}",
        f"candidate_benchmark_manifest_package_path={candidate_benchmark_manifest_package_path or '-'}",
        f"gold_release_package_path={gold_release_package_path or '-'}",
        f"claim_evidence_eval_candidate_export_path={claim_evidence_eval_candidate_export_path or '-'}",
        f"source_correction_log_path={export_source_log_path or '-'}",
        f"claim_evidence_reviewed_eval_fixtures_path={claim_evidence_reviewed_eval_fixtures_path or '-'}",
        f"claim_evidence_reviewed_eval_fixtures_source_reviewed_dir={reviewed_fixture_source_dir or '-'}",
        f"p0_overstatement_review_summary_path={p0_overstatement_review_summary_path or '-'}",
        *(claim_evidence_eval_review_queue_evidence or []),
    ]
    if candidate_benchmark is None:
        return EvidenceGroundingRoadmapCompletionCheck(
            requirement_id="p0_metrics_reported",
            requirement="Report P0 grounding metrics for the candidate.",
            status="fail",
            evidence=[*evidence, "candidate_benchmark_loaded=false"],
            detail="Candidate benchmark report did not load.",
        )
    available = {
        name
        for name, metric in candidate_benchmark.aggregate_gold_scored_metrics.items()
        if name in P0_GOLD_METRIC_NAMES and _is_available_number(metric)
    }
    if (
        p0_overstatement_review_summary is not None
        and p0_overstatement_review_summary.ready_for_p0_metric
        and p0_overstatement_review_summary.overstatement_rate_status.get("status") == "available"
        and isinstance(p0_overstatement_review_summary.overstatement_rate_status.get("value"), (int, float))
    ):
        available.add("overstatement_rate")
        evidence.extend(
            [
                "p0_overstatement_review_summary_ready_for_p0_metric=true",
                "p0_overstatement_review_summary_overstatement_rate="
                f"{p0_overstatement_review_summary.overstatement_rate_status['value']:g}",
                "p0_overstatement_review_summary_included_claim_count="
                f"{p0_overstatement_review_summary.included_claim_count}",
                "p0_overstatement_review_summary_overstated_claim_count="
                f"{p0_overstatement_review_summary.overstated_claim_count}",
            ]
        )
    elif p0_overstatement_review_summary is not None:
        evidence.extend(
            [
                "p0_overstatement_review_summary_ready_for_p0_metric=false",
                "p0_overstatement_review_summary_missing_decision_count="
                f"{p0_overstatement_review_summary.missing_decision_count}",
                "p0_overstatement_review_summary_invalid_decision_count="
                f"{p0_overstatement_review_summary.invalid_decision_count}",
                "p0_overstatement_review_summary_uncertain_claim_count="
                f"{p0_overstatement_review_summary.uncertain_claim_count}",
                "p0_overstatement_review_summary_missing_rationale_count="
                f"{p0_overstatement_review_summary.missing_rationale_count}",
            ]
        )
    if p0_overstatement_review_summary is not None:
        evidence.extend(
            [
                "p0_overstatement_review_summary_source_packet_path="
                f"{p0_overstatement_review_summary.source_packet_path}",
                "p0_overstatement_review_summary_source_reviewed_csv_path="
                f"{p0_overstatement_review_summary.source_reviewed_csv_path or '-'}",
                "p0_overstatement_review_summary_open_issue_csv_path="
                f"{p0_overstatement_review_summary.open_issue_csv_path or '-'}",
            ]
        )
    missing = sorted(P0_GOLD_METRIC_NAMES - available)
    missing_metric_details = _missing_p0_metric_details(candidate_benchmark, missing)
    if "overstatement_rate" in missing:
        evidence.extend(_gold_release_review_failure_code_evidence(gold_release_package_path))
    return EvidenceGroundingRoadmapCompletionCheck(
        requirement_id="p0_metrics_reported",
        requirement=(
            "Report P0 metrics for claim precision, evidence support precision, locator precision, "
            "unsupported claim rate, overstatement rate, limitation recall, and method/result confusion."
        ),
        status="pass" if not missing else "fail",
        evidence=[
            *evidence,
            f"available_p0_metrics={','.join(sorted(available)) or '-'}",
            f"missing_p0_metrics={','.join(missing) or '-'}",
            f"missing_p0_metric_details={missing_metric_details}",
        ],
        detail=(
            "All P0 gold-scored metrics are available in the candidate benchmark."
            if not missing
            else "Candidate benchmark is missing one or more P0 gold-scored metrics."
        ),
    )


def _gold_release_review_failure_code_evidence(gold_release_package_path: Path | None) -> list[str]:
    if gold_release_package_path is None:
        return ["gold_release_review_failure_code_probe=missing_package_path"]
    manifest_paths: list[Path] = []
    try:
        package = _load_json_object(gold_release_package_path)
    except (OSError, ValueError, RuntimeError, json.JSONDecodeError):
        return ["gold_release_review_failure_code_probe=package_load_error"]
    raw_manifest_paths = package.get("manifest_paths")
    if isinstance(raw_manifest_paths, list):
        for raw_path in raw_manifest_paths:
            if isinstance(raw_path, str) and raw_path.strip():
                manifest_paths.append(
                    _resolve_related_review_path(raw_path, base_path=gold_release_package_path)
                )
    raw_source_manifests = package.get("source_split_manifests")
    if isinstance(raw_source_manifests, list):
        for item in raw_source_manifests:
            if not isinstance(item, dict):
                continue
            raw_path = item.get("manifest_out")
            if isinstance(raw_path, str) and raw_path.strip():
                manifest_paths.append(
                    _resolve_related_review_path(raw_path, base_path=gold_release_package_path)
                )
    unique_manifest_paths = list(dict.fromkeys(manifest_paths))
    if not unique_manifest_paths:
        return ["gold_release_review_failure_code_probe=missing_manifest_paths"]

    manifest_count = 0
    manifest_load_error_count = 0
    gold_item_count = 0
    gold_load_error_count = 0
    code_counts: dict[str, int] = {}
    gold_paths: set[str] = set()
    overstated_result_gold_paths: set[str] = set()
    for manifest_path in unique_manifest_paths:
        try:
            manifest = _load_json_object(manifest_path)
        except (OSError, ValueError, RuntimeError, json.JSONDecodeError):
            manifest_load_error_count += 1
            continue
        manifest_count += 1
        items = manifest.get("items")
        if not isinstance(items, list):
            continue
        for item in items:
            if not isinstance(item, dict):
                continue
            raw_gold_path = item.get("gold_path")
            if not isinstance(raw_gold_path, str) or not raw_gold_path.strip():
                continue
            gold_item_count += 1
            resolved_gold_path = _resolve_related_review_path(raw_gold_path, base_path=manifest_path)
            gold_paths.add(str(resolved_gold_path))
            try:
                gold = _load_json_object(resolved_gold_path)
            except (OSError, ValueError, RuntimeError, json.JSONDecodeError):
                gold_load_error_count += 1
                continue
            for code in _iter_review_failure_codes(gold):
                code_counts[code] = code_counts.get(code, 0) + 1
                if code == "OVERSTATED_RESULT":
                    overstated_result_gold_paths.add(str(resolved_gold_path))

    status = "ok"
    if manifest_load_error_count or gold_load_error_count:
        status = "partial"
    return [
        f"gold_release_review_failure_code_probe={status}",
        f"gold_release_manifest_count={manifest_count}",
        f"gold_release_manifest_load_error_count={manifest_load_error_count}",
        f"gold_release_gold_item_count={gold_item_count}",
        f"gold_release_gold_load_error_count={gold_load_error_count}",
        f"gold_release_gold_path_count={len(gold_paths)}",
        f"gold_release_gold_paths_sample={_evidence_value_sample(gold_paths)}",
        f"gold_release_review_failure_code_counts={_format_count_map(code_counts)}",
        f"gold_release_overstated_result_label_count={code_counts.get('OVERSTATED_RESULT', 0)}",
        "gold_release_overstated_result_gold_paths_sample="
        f"{_evidence_value_sample(overstated_result_gold_paths)}",
    ]


def _iter_review_failure_codes(payload: Any) -> list[str]:
    codes: list[str] = []
    if isinstance(payload, dict):
        for key, value in payload.items():
            if key == "review_failure_codes" and isinstance(value, list):
                codes.extend(str(item).strip() for item in value if str(item).strip())
            else:
                codes.extend(_iter_review_failure_codes(value))
    elif isinstance(payload, list):
        for item in payload:
            codes.extend(_iter_review_failure_codes(item))
    return codes


def _missing_p0_metric_details(
    candidate_benchmark: EvidenceGroundingBenchmarkReport,
    missing_metric_names: list[str],
) -> str:
    summaries: list[str] = []
    for metric_name in missing_metric_names:
        aggregate_metric = candidate_benchmark.aggregate_gold_scored_metrics.get(metric_name)
        aggregate_status = getattr(aggregate_metric, "status", None) or "missing"
        aggregate_item_count = getattr(aggregate_metric, "item_count", None)
        item_available = 0
        item_not_available = 0
        item_missing = 0
        sources: list[str] = []
        details: list[str] = []
        for scorecard_item in candidate_benchmark.scorecards:
            metric = getattr(scorecard_item.scorecard.gold_scored_metrics, metric_name, None)
            if metric is None:
                item_missing += 1
                continue
            if _is_available_number(metric):
                item_available += 1
            else:
                item_not_available += 1
            source = _safe_metric_detail_token(getattr(metric, "source", None))
            detail = _safe_metric_detail_token(getattr(metric, "detail", None))
            if source and source not in sources:
                sources.append(source)
            if detail and detail not in details:
                details.append(detail)
        parts = [
            metric_name,
            f"aggregate_status={aggregate_status}",
            f"aggregate_item_count={aggregate_item_count if aggregate_item_count is not None else '-'}",
            f"item_available={item_available}",
            f"item_not_available={item_not_available}",
            f"item_missing={item_missing}",
        ]
        if sources:
            parts.append(f"sources={'+'.join(sources[:3])}")
        if details:
            parts.append(f"details={'+'.join(details[:2])}")
        summaries.append(":".join(parts))
    return ";".join(summaries) or "-"


def _safe_metric_detail_token(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    return re.sub(r"[\s,;:]+", "_", text)


def _roadmap_check_p0_regression_gate(
    comparison_report: EvidenceGroundingScorecardComparisonReport | None,
) -> EvidenceGroundingRoadmapCompletionCheck:
    if comparison_report is None:
        return EvidenceGroundingRoadmapCompletionCheck(
            requirement_id="p0_regression_gate",
            requirement="Fail a candidate when P0 grounding metrics regress.",
            status="fail",
            evidence=["comparison_report_loaded=false"],
            detail="Comparison report did not load.",
        )
    gated = set(comparison_report.gate_metric_names)
    missing = sorted(P0_GOLD_METRIC_NAMES - gated)
    passed = comparison_report.gate_policy == "p0_gold" and not missing and comparison_report.decision.compared_metric_count > 0
    return EvidenceGroundingRoadmapCompletionCheck(
        requirement_id="p0_regression_gate",
        requirement="Fail a candidate when P0 grounding metrics regress.",
        status="pass" if passed else "fail",
        evidence=[
            f"gate_policy={comparison_report.gate_policy}",
            f"gate_metric_names={','.join(comparison_report.gate_metric_names) or '-'}",
            f"compared_metric_count={comparison_report.decision.compared_metric_count}",
            f"missing_p0_gate_metrics={','.join(missing) or '-'}",
        ],
        detail=(
            "Comparison report used the P0 gold gate over all P0 metrics."
            if passed
            else "Comparison report does not prove that all P0 metrics were gated for regression failure."
        ),
    )


