                f"ready_gold_reviewer_handoff_release_prep_package_count={handoff_inventory.get('ready_release_prep_package_count', 0)}",
                "ready_gold_reviewer_handoff_release_prep_package_paths_sample="
                f"{handoff_inventory.get('ready_release_prep_package_paths_sample', '-')}",
                "ready_gold_reviewer_handoff_release_prep_release_package_paths_sample="
                f"{handoff_inventory.get('ready_release_prep_release_package_paths_sample', '-')}",
                "ready_gold_reviewer_handoff_release_prep_readiness_report_paths_sample="
                f"{handoff_inventory.get('ready_release_prep_readiness_report_paths_sample', '-')}",
                f"blocked_gold_reviewer_handoff_release_prep_package_count={handoff_inventory.get('blocked_release_prep_package_count', 0)}",
