def _workspace_candidate_lineage_evidence_paths(root: Path) -> list[Path]:
    names = (
        "candidate_lineage_run_dir_map_with_dubois_backfill.json",
        "candidate_lineage_run_dir_map.json",
        "candidate_lineage_run_dir_map_discovery.json",
        "scorecard_input_backfill.json",
        "candidate_lineage_dubois_scorecard_input_backfill.json",
        "candidate_lineage_patch_template.json",
        "candidate_lineage_patch_template_prefilled.json",
        "candidate_lineage_patch_template_fill_readiness.json",
        "candidate_lineage_patch_template_prefilled_fill_readiness.json",
        "candidate_lineage_patch_template_fill_tasks.json",
        "candidate_lineage_patch_template_prefilled_fill_tasks.json",
        "candidate_lineage_patch_template_fill_review_status.json",
        "candidate_lineage_patch_template_prefilled_fill_review_status.json",
        "manifest_package.json",
    )
    patterns = (
        "*scorecard_input_backfill*.json",
    )
    candidates: list[Path] = []
    if root.is_file():
        candidates.append(root)
    elif root.exists():
        for name in names:
            candidates.extend(path for path in root.rglob(name) if path.is_file())
            parent_candidate = root.parent / name
            if parent_candidate.is_file():
                candidates.append(parent_candidate)
        for pattern in patterns:
            candidates.extend(path for path in root.rglob(pattern) if path.is_file())
    seen: set[Path] = set()
    out: list[Path] = []
    for candidate in candidates:
        resolved = candidate.expanduser().resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        out.append(resolved)
    return out


