def _comparison_decision_consistency_findings(payload: dict[str, Any]) -> list[str]:
    findings: set[str] = set()
    decision = payload.get("decision")
    if not isinstance(decision, dict):
        findings.add("comparison_decision_invalid")
        return sorted(findings)

    comparisons = payload.get("comparisons")
    if not isinstance(comparisons, list):
        findings.add("comparison_comparisons_invalid")
        comparisons = []
    stage_metric_comparisons = payload.get("stage_metric_comparisons")
    if stage_metric_comparisons is None:
        stage_metric_comparisons = []
    if not isinstance(stage_metric_comparisons, list):
        findings.add("comparison_stage_metric_comparisons_invalid")
        stage_metric_comparisons = []
    failure_count_comparisons = payload.get("failure_count_comparisons")
    if failure_count_comparisons is None:
        failure_count_comparisons = []
    if not isinstance(failure_count_comparisons, list):
        findings.add("comparison_failure_count_comparisons_invalid")
        failure_count_comparisons = []
    threshold_checks = payload.get("threshold_checks")
    if threshold_checks is None:
        threshold_checks = []
    if not isinstance(threshold_checks, list):
        findings.add("comparison_threshold_checks_invalid")
        threshold_checks = []

    gate_metric_names = payload.get("gate_metric_names")
    if gate_metric_names is None:
        gate_metric_names = []
    if not isinstance(gate_metric_names, list) or any(
        not isinstance(value, str) for value in gate_metric_names
    ):
        findings.add("comparison_gate_metric_names_invalid")
        gate_metric_names = []
    gate_names = {value.strip() for value in gate_metric_names if value.strip()}

    def gated_metric(comparison: dict[str, Any]) -> bool:
        if not gate_names:
            return True
        name = comparison.get("name")
        metric_group = comparison.get("metric_group")
        return (
            isinstance(name, str)
            and (
                name in gate_names
                or (isinstance(metric_group, str) and f"{metric_group}.{name}" in gate_names)
            )
        )

    def gated_stage_metric(comparison: dict[str, Any]) -> bool:
        if not gate_names:
            return True
        name = comparison.get("name")
        stage = comparison.get("stage")
        metric_group = comparison.get("metric_group")
        if not isinstance(name, str):
            return False
        return (
            name in gate_names
            or (isinstance(metric_group, str) and f"{metric_group}.{name}" in gate_names)
            or (
                isinstance(stage, str)
                and isinstance(metric_group, str)
                and f"{stage}.{metric_group}.{name}" in gate_names
            )
        )

    failed_checks: list[str] = []
    regressions: list[str] = []
    comparable_metric_count = 0

    for comparison in comparisons:
        if not isinstance(comparison, dict):
            findings.add("comparison_metric_comparison_invalid")
            continue
        comparable_metric_count += 1
        if gated_metric(comparison):
            name = comparison.get("name")
            if comparison.get("passed") is False and isinstance(name, str):
                failed_checks.append(name)
            if comparison.get("regression") is True and isinstance(name, str):
                regressions.append(name)

    for comparison in stage_metric_comparisons:
        if not isinstance(comparison, dict):
            findings.add("comparison_stage_metric_comparison_invalid")
            continue
        comparable_metric_count += 1
        if not gated_stage_metric(comparison):
            continue
        stage = comparison.get("stage")
        metric_group = comparison.get("metric_group")
        name = comparison.get("name")
        if not (isinstance(stage, str) and isinstance(metric_group, str) and isinstance(name, str)):
            findings.add("comparison_stage_metric_comparison_invalid")
            continue
        check_name = f"stage_metric_summary.{stage}.{metric_group}.{name}"
        if comparison.get("passed") is False:
            failed_checks.append(check_name)
        if comparison.get("regression") is True:
            regressions.append(check_name)

    for comparison in failure_count_comparisons:
        if not isinstance(comparison, dict):
            findings.add("comparison_failure_count_comparison_invalid")
            continue
        metric_group = comparison.get("metric_group")
        name = comparison.get("name")
        if not (isinstance(metric_group, str) and isinstance(name, str)):
            findings.add("comparison_failure_count_comparison_invalid")
            continue
        check_name = f"{metric_group}.{name}"
        if comparison.get("passed") is False:
            failed_checks.append(check_name)
        if comparison.get("regression") is True:
            regressions.append(check_name)

    for check in threshold_checks:
        if not isinstance(check, dict):
            findings.add("comparison_threshold_check_invalid")
            continue
        if check.get("passed") is not False:
            continue
        metric_group = check.get("metric_group")
        name = check.get("name")
        stage = check.get("stage")
        if not (isinstance(metric_group, str) and isinstance(name, str)):
            findings.add("comparison_threshold_check_invalid")
            continue
        if isinstance(stage, str) and stage.strip():
            failed_checks.append(f"thresholds.stage_metric_summary.{stage}.{metric_group}.{name}")
        else:
            failed_checks.append(f"thresholds.{metric_group}.{name}")

    baseline = payload.get("baseline")
    candidate = payload.get("candidate")
    if isinstance(baseline, dict) and isinstance(candidate, dict):
        failed_checks.extend(_benchmark_context_failures(baseline_label=baseline, candidate_label=candidate))
    elif baseline is not None or candidate is not None:
        findings.add("comparison_context_invalid")

    compared_metric_count = _payload_json_int(decision, "compared_metric_count")
    if compared_metric_count is None or compared_metric_count < 0:
        findings.add("comparison_decision_compared_metric_count_invalid")
    elif compared_metric_count != comparable_metric_count:
        findings.add("comparison_decision_compared_metric_count_mismatch")

    observed_failed_checks = decision.get("failed_checks")
    if not isinstance(observed_failed_checks, list) or any(
        not isinstance(value, str) for value in observed_failed_checks
    ):
        findings.add("comparison_decision_failed_checks_invalid")
    elif sorted(value.strip() for value in observed_failed_checks if value.strip()) != sorted(failed_checks):
        findings.add("comparison_decision_failed_checks_mismatch")

    observed_regressions = decision.get("regressions")
    if not isinstance(observed_regressions, list) or any(
        not isinstance(value, str) for value in observed_regressions
    ):
        findings.add("comparison_decision_regressions_invalid")
    elif sorted(value.strip() for value in observed_regressions if value.strip()) != sorted(regressions):
        findings.add("comparison_decision_regressions_mismatch")

    expected_passed = comparable_metric_count > 0 and not failed_checks and not regressions
    if not isinstance(decision.get("passed"), bool):
        findings.add("comparison_decision_passed_invalid")
    elif decision.get("passed") != expected_passed:
        findings.add("comparison_decision_passed_mismatch")
    return sorted(findings)


def _threshold_calibration_count_findings(payload: dict[str, Any]) -> list[str]:
    findings: set[str] = set()
    report_count = _payload_json_int(payload, "report_count")
    if report_count is None or report_count < 0:
        findings.add("threshold_calibration_report_count_invalid")

    recommendations = payload.get("recommendations")
    if not isinstance(recommendations, list):
        findings.add("threshold_calibration_recommendations_invalid")
        return sorted(findings)

    for recommendation in recommendations:
        if not isinstance(recommendation, dict):
            findings.add("threshold_calibration_recommendation_invalid")
            continue
        recommendation_report_count = _payload_json_int(recommendation, "report_count")
        available_count = _payload_json_int(recommendation, "available_count")
        if recommendation_report_count is None or recommendation_report_count < 0:
            findings.add("threshold_calibration_recommendation_report_count_invalid")
        if available_count is None or available_count < 0:
            findings.add("threshold_calibration_recommendation_available_count_invalid")

        if (
            report_count is not None
            and report_count >= 0
            and recommendation_report_count is not None
            and recommendation_report_count >= 0
            and recommendation_report_count != report_count
        ):
            findings.add("threshold_calibration_recommendation_report_count_mismatch")

        observed_values = recommendation.get("observed_values")
        observed_count: int | None = None
        if not isinstance(observed_values, list) or any(
            not isinstance(value, (int, float)) for value in observed_values
        ):
            findings.add("threshold_calibration_recommendation_observed_values_invalid")
        else:
            observed_count = len(observed_values)

        source_reports = recommendation.get("source_reports")
        source_report_count: int | None = None
        if not isinstance(source_reports, list) or any(not isinstance(value, str) for value in source_reports):
            findings.add("threshold_calibration_recommendation_source_reports_invalid")
        else:
            source_report_count = len(source_reports)

        if available_count is not None and available_count >= 0:
            if observed_count is not None and available_count != observed_count:
                findings.add("threshold_calibration_recommendation_available_count_mismatch")
            if source_report_count is not None and available_count != source_report_count:
                findings.add("threshold_calibration_recommendation_available_count_mismatch")
            if (
                recommendation_report_count is not None
                and recommendation_report_count >= 0
                and available_count > recommendation_report_count
            ):
                findings.add("threshold_calibration_recommendation_report_count_mismatch")
            if report_count is not None and report_count >= 0 and available_count > report_count:
                findings.add("threshold_calibration_recommendation_report_count_mismatch")
        if (
            source_report_count is not None
            and recommendation_report_count is not None
            and recommendation_report_count >= 0
            and source_report_count > recommendation_report_count
        ):
            findings.add("threshold_calibration_recommendation_report_count_mismatch")
        if (
            source_report_count is not None
            and report_count is not None
            and report_count >= 0
            and source_report_count > report_count
        ):
            findings.add("threshold_calibration_recommendation_report_count_mismatch")

        status = recommendation.get("status")
        if status == "available" and available_count == 0:
            findings.add("threshold_calibration_available_recommendation_has_no_values")
        if status == "not_available" and available_count not in (0, None):
            findings.add("threshold_calibration_not_available_recommendation_has_values")
    return sorted(findings)


def _threshold_adoption_review_count_findings(payload: dict[str, Any]) -> list[str]:
    findings: set[str] = set()
    raw_counts: dict[str, int] = {}
    for field_name in ("pass_count", "warn_count", "fail_count"):
        value = _payload_json_int(payload, field_name)
        if value is None or value < 0:
            findings.add(f"threshold_adoption_{field_name}_invalid")
        else:
            raw_counts[field_name] = value

    checks = payload.get("checks")
    if not isinstance(checks, list):
        findings.add("threshold_adoption_checks_invalid")
        return sorted(findings)

    actual_counts = {"pass_count": 0, "warn_count": 0, "fail_count": 0}
    actual_blockers: list[str] = []
    check_statuses_known = True
    for check in checks:
        if not isinstance(check, dict):
            findings.add("threshold_adoption_check_invalid")
            check_statuses_known = False
            continue
        status = check.get("status")
        name = check.get("name")
        if status == "pass":
            actual_counts["pass_count"] += 1
        elif status == "warn":
            actual_counts["warn_count"] += 1
        elif status == "fail":
            actual_counts["fail_count"] += 1
            if isinstance(name, str) and name.strip():
                actual_blockers.append(name.strip())
        else:
            findings.add("threshold_adoption_check_status_invalid")
            check_statuses_known = False

    if check_statuses_known:
        for field_name, actual_count in actual_counts.items():
            if raw_counts.get(field_name) != actual_count:
                findings.add(f"threshold_adoption_{field_name}_mismatch")

        blockers = payload.get("blockers")
        if not isinstance(blockers, list) or any(not isinstance(value, str) for value in blockers):
            findings.add("threshold_adoption_blockers_invalid")
        elif sorted(value.strip() for value in blockers if value.strip()) != sorted(actual_blockers):
            findings.add("threshold_adoption_blockers_mismatch")

        ready = payload.get("production_threshold_ready")
        raw_blockers = payload.get("blockers")
        raw_blocker_present = isinstance(raw_blockers, list) and any(
            isinstance(value, str) and value.strip() for value in raw_blockers
        )
        raw_fail_count = raw_counts.get("fail_count")
        if ready is True and (
            actual_counts["fail_count"] > 0
            or bool(actual_blockers)
            or (raw_fail_count is not None and raw_fail_count > 0)
            or raw_blocker_present
        ):
            findings.add("threshold_adoption_ready_with_failures")
        if ready is False and actual_counts["fail_count"] == 0 and not actual_blockers:
            findings.add("threshold_adoption_not_ready_without_failures")
        if not isinstance(ready, bool):
            findings.add("threshold_adoption_production_threshold_ready_invalid")
    return sorted(findings)


def _threshold_adoption_package_count_findings(
    payload: dict[str, Any],
    *,
    base_path: Path | None = None,
) -> list[str]:
    findings: set[str] = set()
    raw_counts: dict[str, int] = {}
    for field_name in (
        "comparison_suite_count",
        "production_threshold_ready_count",
        "production_threshold_blocked_count",
    ):
        value = _payload_json_int(payload, field_name)
        if value is None or value < 0:
            findings.add(f"threshold_adoption_package_{field_name}_invalid")
        else:
            raw_counts[field_name] = value

    path_counts: list[int] = []
    for field_name in (
        "threshold_checked_comparison_report_paths",
        "threshold_adoption_review_paths",
    ):
        values = payload.get(field_name)
        if not isinstance(values, list) or any(not isinstance(value, str) for value in values):
            findings.add(f"threshold_adoption_package_{field_name}_invalid")
            continue
        path_counts.append(len(values))
        suite_count = raw_counts.get("comparison_suite_count")
        if suite_count is not None and suite_count != len(values):
            findings.add("threshold_adoption_package_comparison_suite_count_mismatch")

    review_path_count = path_counts[-1] if len(path_counts) == 2 else None
    ready_count = raw_counts.get("production_threshold_ready_count")
    blocked_count = raw_counts.get("production_threshold_blocked_count")
    if (
        review_path_count is not None
        and ready_count is not None
        and blocked_count is not None
        and ready_count + blocked_count != review_path_count
    ):
        findings.add("threshold_adoption_package_production_threshold_summary_count_mismatch")

    embedded_reviews = payload.get("threshold_adoption_reviews")
    if "threshold_adoption_reviews" in payload and not isinstance(embedded_reviews, list):
        findings.add("threshold_adoption_package_threshold_adoption_reviews_invalid")
    if isinstance(embedded_reviews, list) and embedded_reviews:
        embedded_ready_count = 0
        embedded_blocked_count = 0
        embedded_status_known = True
        for review in embedded_reviews:
            if not isinstance(review, dict):
                findings.add("threshold_adoption_package_threshold_adoption_review_item_invalid")
                embedded_status_known = False
                continue
            status = review.get("production_threshold_ready")
            if status is True:
                embedded_ready_count += 1
            elif status is False:
                embedded_blocked_count += 1
            else:
                findings.add("threshold_adoption_package_threshold_adoption_review_status_invalid")
                embedded_status_known = False

        suite_count = raw_counts.get("comparison_suite_count")
        if suite_count is not None and suite_count != len(embedded_reviews):
            findings.add("threshold_adoption_package_comparison_suite_count_mismatch")
        if embedded_status_known:
            if ready_count is not None and ready_count != embedded_ready_count:
                findings.add("threshold_adoption_package_production_threshold_ready_count_mismatch")
            if blocked_count is not None and blocked_count != embedded_blocked_count:
                findings.add("threshold_adoption_package_production_threshold_blocked_count_mismatch")

    if base_path is not None and isinstance(values := payload.get("threshold_adoption_review_paths"), list):
        linked_ready_count = 0
        linked_blocked_count = 0
        linked_status_known = True
        for raw_path in values:
            if not isinstance(raw_path, str):
                continue
            try:
                linked_payload = _load_json_object(_resolve_related_review_path(raw_path, base_path=base_path))
            except (OSError, ValueError, json.JSONDecodeError, RuntimeError):
                findings.add("threshold_adoption_package_linked_review_load_failed")
                linked_status_known = False
                continue
            if linked_payload.get("schema_version") != "evidence_grounding_threshold_adoption_review.v1":
                findings.add("threshold_adoption_package_linked_review_schema_version_invalid")
                linked_status_known = False
                continue
            linked_findings = _threshold_adoption_review_count_findings(linked_payload)
            for finding in linked_findings:
                findings.add(f"threshold_adoption_package_linked_review_{finding}")
            status = linked_payload.get("production_threshold_ready")
            if status is True:
                linked_ready_count += 1
            elif status is False:
                linked_blocked_count += 1
            else:
                findings.add("threshold_adoption_package_linked_review_status_invalid")
                linked_status_known = False

        if linked_status_known:
            if ready_count is not None and ready_count != linked_ready_count:
                findings.add("threshold_adoption_package_linked_review_ready_count_mismatch")
            if blocked_count is not None and blocked_count != linked_blocked_count:
                findings.add("threshold_adoption_package_linked_review_blocked_count_mismatch")
    return sorted(findings)


def _fixed_goldset_run_readiness_artifact_findings(payload: dict[str, Any]) -> list[str]:
    lane_summaries = payload.get("lane_summaries")
    if not isinstance(lane_summaries, list):
        return []
    findings: list[str] = []
    raw_pass_count = _payload_json_int(payload, "pass_count")
    raw_fail_count = _payload_json_int(payload, "fail_count")
    if raw_pass_count is None or raw_pass_count < 0:
        findings.append("fixed_goldset_run_readiness_pass_count_invalid")
    if raw_fail_count is None or raw_fail_count < 0:
        findings.append("fixed_goldset_run_readiness_fail_count_invalid")
    total_pass_count = 0
    total_fail_count = 0
    lane_status_counts_known = True
    total_malformed_count = 0
    total_malformed_count_known = True
    for lane in lane_summaries:
        if not isinstance(lane, dict):
            findings.append("fixed_goldset_run_readiness_lane_summary_invalid")
            lane_status_counts_known = False
            continue
        lane_pass_count = _payload_json_int(lane, "pass_count")
        lane_fail_count = _payload_json_int(lane, "fail_count")
        if lane_pass_count is None or lane_pass_count < 0:
            findings.append("fixed_goldset_run_readiness_lane_pass_count_invalid")
            lane_status_counts_known = False
        else:
            total_pass_count += lane_pass_count
        if lane_fail_count is None or lane_fail_count < 0:
            findings.append("fixed_goldset_run_readiness_lane_fail_count_invalid")
            lane_status_counts_known = False
        else:
            total_fail_count += lane_fail_count
        lane_count = _payload_json_int(lane, "malformed_required_artifact_count")
        if lane_count is None or lane_count < 0:
            findings.append("fixed_goldset_run_readiness_malformed_required_artifact_count_missing")
            total_malformed_count_known = False
        else:
            total_malformed_count += lane_count
        items = lane.get("items")
        if not isinstance(items, list):
            continue
        item_pass_count = 0
        item_fail_count = 0
        item_status_count_known = True
        item_malformed_count = 0
        item_count_known = True
        for item in items:
            if not isinstance(item, dict):
                findings.append("fixed_goldset_run_readiness_item_invalid")
                item_status_count_known = False
                item_count_known = False
                continue
            status = item.get("status")
            if status == "pass":
                item_pass_count += 1
            elif status == "fail":
                item_fail_count += 1
            else:
                findings.append("fixed_goldset_run_readiness_item_status_invalid")
                item_status_count_known = False
            if "malformed_required_artifacts" not in item:
                findings.append("fixed_goldset_run_readiness_item_malformed_required_artifacts_missing")
                item_count_known = False
                continue
            malformed = item.get("malformed_required_artifacts")
            if not isinstance(malformed, list) or any(not isinstance(value, str) for value in malformed):
                findings.append("fixed_goldset_run_readiness_item_malformed_required_artifacts_invalid")
                item_count_known = False
                continue
            item_malformed_count += len(malformed)
            if item.get("status") == "pass" and malformed:
                findings.append("fixed_goldset_run_readiness_pass_item_has_malformed_required_artifacts")
        if item_status_count_known:
            if lane_pass_count is not None and lane_pass_count >= 0 and lane_pass_count != item_pass_count:
                findings.append("fixed_goldset_run_readiness_lane_pass_count_mismatch")
            if lane_fail_count is not None and lane_fail_count >= 0 and lane_fail_count != item_fail_count:
                findings.append("fixed_goldset_run_readiness_lane_fail_count_mismatch")
        if lane_count is not None and lane_count >= 0 and item_count_known and lane_count != item_malformed_count:
            findings.append("fixed_goldset_run_readiness_malformed_required_artifact_count_mismatch")
    if lane_status_counts_known:
        if raw_pass_count is not None and raw_pass_count >= 0 and raw_pass_count != total_pass_count:
            findings.append("fixed_goldset_run_readiness_pass_count_mismatch")
        if raw_fail_count is not None and raw_fail_count >= 0 and raw_fail_count != total_fail_count:
            findings.append("fixed_goldset_run_readiness_fail_count_mismatch")
    if payload.get("comparison_run_ready") is True and total_malformed_count_known and total_malformed_count > 0:
        findings.append("fixed_goldset_run_readiness_ready_with_malformed_required_artifacts")
    if payload.get("comparison_run_ready") is True and lane_status_counts_known and total_fail_count > 0:
        findings.append("fixed_goldset_run_readiness_ready_with_failures")
    return findings


def _fixed_goldset_comparison_suite_readiness_findings(
    payload: dict[str, Any],
    *,
    base_path: Path | None,
) -> list[str]:
    findings: list[str] = []
    comparison_run_ready = payload.get("comparison_run_ready")
    if not isinstance(comparison_run_ready, bool):
        findings.append("fixed_goldset_comparison_suite_comparison_run_ready_invalid")
    run_readiness_fail_count = _payload_json_int(payload, "run_readiness_fail_count")
    if run_readiness_fail_count is None or run_readiness_fail_count < 0:
        findings.append("fixed_goldset_comparison_suite_run_readiness_fail_count_invalid")

    raw_run_readiness_path = payload.get("run_readiness_report_path")
    if not isinstance(raw_run_readiness_path, str) or not raw_run_readiness_path.strip():
        return findings
    if base_path is None:
        return findings
    try:
        run_readiness_path = _resolve_related_review_path(raw_run_readiness_path, base_path=base_path)
        run_readiness_payload = _load_json_object(run_readiness_path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        findings.append(f"fixed_goldset_comparison_suite_run_readiness_load_failed: {exc}")
        return findings
    if run_readiness_payload.get("schema_version") != "evidence_grounding_fixed_goldset_run_readiness.v1":
        findings.append("fixed_goldset_comparison_suite_run_readiness_schema_invalid")
        return findings
    linked_ready = run_readiness_payload.get("comparison_run_ready")
    if isinstance(comparison_run_ready, bool) and isinstance(linked_ready, bool) and comparison_run_ready != linked_ready:
        findings.append("fixed_goldset_comparison_suite_comparison_run_ready_mismatch")
    linked_fail_count = _payload_json_int(run_readiness_payload, "fail_count")
    if (
        run_readiness_fail_count is not None
        and run_readiness_fail_count >= 0
        and linked_fail_count is not None
        and linked_fail_count >= 0
        and run_readiness_fail_count != linked_fail_count
    ):
        findings.append("fixed_goldset_comparison_suite_run_readiness_fail_count_mismatch")
    if comparison_run_ready is True and linked_fail_count is not None and linked_fail_count > 0:
        findings.append("fixed_goldset_comparison_suite_ready_with_run_readiness_failures")
    findings.extend(
        f"fixed_goldset_comparison_suite_linked_{finding}"
        for finding in _fixed_goldset_run_readiness_artifact_findings(run_readiness_payload)
    )
    return findings


def _fixed_goldset_comparison_suite_package_count_findings(
    payload: dict[str, Any],
    *,
    base_path: Path | None = None,
) -> list[str]:
    findings: list[str] = []
    raw_counts: dict[str, int] = {}
    for field_name in (
        "suite_count",
        "comparison_pass_count",
        "comparison_fail_count",
        "run_readiness_fail_count",
    ):
        value = _payload_json_int(payload, field_name)
        if value is None or value < 0:
            findings.append(f"fixed_goldset_comparison_suite_package_{field_name}_invalid")
        else:
            raw_counts[field_name] = value

    suite_paths = payload.get("comparison_suite_paths")
    comparison_report_paths = payload.get("comparison_report_paths")
    run_readiness_report_paths = payload.get("run_readiness_report_paths")
    comparison_suites = payload.get("comparison_suites")
    for field_name, value in (
        ("comparison_suite_paths", suite_paths),
        ("comparison_report_paths", comparison_report_paths),
        ("run_readiness_report_paths", run_readiness_report_paths),
    ):
        if not isinstance(value, list):
            findings.append(f"fixed_goldset_comparison_suite_package_{field_name}_invalid")
    if "comparison_suites" in payload and not isinstance(comparison_suites, list):
        findings.append("fixed_goldset_comparison_suite_package_comparison_suites_invalid")

    suite_count = raw_counts.get("suite_count")
    if suite_count is not None:
        suite_count_mismatch = False
        for field_name, value in (
            ("comparison_suite_paths", suite_paths),
            ("comparison_report_paths", comparison_report_paths),
            ("run_readiness_report_paths", run_readiness_report_paths),
        ):
            if isinstance(value, list) and suite_count != len(value):
                suite_count_mismatch = True
                findings.append(f"fixed_goldset_comparison_suite_package_{field_name}_count_mismatch")
        if isinstance(comparison_suites, list) and comparison_suites and suite_count != len(comparison_suites):
            suite_count_mismatch = True
            findings.append("fixed_goldset_comparison_suite_package_comparison_suites_count_mismatch")
        if suite_count_mismatch:
            findings.append("fixed_goldset_comparison_suite_package_suite_count_mismatch")
        if (
            "comparison_pass_count" in raw_counts
            and "comparison_fail_count" in raw_counts
            and raw_counts["comparison_pass_count"] + raw_counts["comparison_fail_count"] != suite_count
        ):
            findings.append("fixed_goldset_comparison_suite_package_decision_count_mismatch")

    if isinstance(comparison_suites, list) and comparison_suites:
        embedded_pass_count = 0
        embedded_fail_count = 0
        embedded_run_readiness_fail_count = 0
        embedded_counts_known = True
        for suite in comparison_suites:
            if not isinstance(suite, dict):
                findings.append("fixed_goldset_comparison_suite_package_suite_item_invalid")
                embedded_counts_known = False
                continue
            comparison_passed = suite.get("comparison_passed")
            if comparison_passed is True:
                embedded_pass_count += 1
            elif comparison_passed is False:
                embedded_fail_count += 1
            else:
                findings.append("fixed_goldset_comparison_suite_package_suite_item_comparison_passed_invalid")
                embedded_counts_known = False
            run_readiness_fail_count = _payload_json_int(suite, "run_readiness_fail_count")
            if run_readiness_fail_count is None or run_readiness_fail_count < 0:
                findings.append("fixed_goldset_comparison_suite_package_suite_item_run_readiness_fail_count_invalid")
                embedded_counts_known = False
            else:
                embedded_run_readiness_fail_count += run_readiness_fail_count
        if embedded_counts_known:
            if raw_counts.get("comparison_pass_count") != embedded_pass_count:
                findings.append("fixed_goldset_comparison_suite_package_comparison_pass_count_mismatch")
            if raw_counts.get("comparison_fail_count") != embedded_fail_count:
                findings.append("fixed_goldset_comparison_suite_package_comparison_fail_count_mismatch")
            if raw_counts.get("run_readiness_fail_count") != embedded_run_readiness_fail_count:
                findings.append("fixed_goldset_comparison_suite_package_run_readiness_fail_count_mismatch")

    if base_path is not None:
        for label, path_field in (
            ("baseline", "baseline_run_package_path"),
            ("candidate", "candidate_run_package_path"),
        ):
            raw_path = payload.get(path_field)
            if not isinstance(raw_path, str) or not raw_path.strip():
                continue
            prefix = f"fixed_goldset_comparison_suite_package_{label}_run_package"
            try:
                run_payload = _load_json_object(_resolve_related_review_path(raw_path, base_path=base_path))
            except (OSError, ValueError, json.JSONDecodeError, RuntimeError):
                findings.append(f"{prefix}_load_failed")
                continue
            if run_payload.get("schema_version") != "evidence_grounding_benchmark_run_package.v1":
                findings.append(f"{prefix}_schema_version_invalid")
                continue
            for finding in _benchmark_run_package_count_findings(run_payload):
                findings.append(f"{prefix}_{finding}")
            _extend_comparison_suite_package_run_package_context_findings(
                findings=findings,
                payload=payload,
                run_payload=run_payload,
                label=label,
            )
    return findings


def _extend_comparison_suite_package_run_package_context_findings(
    *,
    findings: list[str],
    payload: dict[str, Any],
    run_payload: dict[str, Any],
    label: str,
) -> None:
    prefix = f"fixed_goldset_comparison_suite_package_{label}_run_package"
    required_fields = {
        "scorecard_readiness_pass_count",
        "scorecard_readiness_warn_count",
        "scorecard_readiness_fail_count",
        "scorecard_not_ready_candidate_ids",
    }
    linked_fields_present = required_fields <= run_payload.keys()
    package_fields_present = payload.get(f"{label}_run_package_scorecard_readiness_fields_present")
    if isinstance(package_fields_present, bool) and package_fields_present != linked_fields_present:
        findings.append(f"{prefix}_scorecard_readiness_fields_present_mismatch")
    for count_name in ("pass", "warn", "fail"):
        package_count = _payload_json_int(payload, f"{label}_scorecard_readiness_{count_name}_count")
        linked_count = _payload_json_int(run_payload, f"scorecard_readiness_{count_name}_count")
        if package_count is not None and linked_count is not None and package_count != linked_count:
            findings.append(f"{prefix}_scorecard_readiness_{count_name}_count_mismatch")
    package_not_ready_ids = payload.get(f"{label}_scorecard_not_ready_candidate_ids")
    linked_not_ready_ids = run_payload.get("scorecard_not_ready_candidate_ids")
    if (
        isinstance(package_not_ready_ids, list)
        and all(isinstance(value, str) for value in package_not_ready_ids)
        and isinstance(linked_not_ready_ids, list)
        and all(isinstance(value, str) for value in linked_not_ready_ids)
        and sorted(package_not_ready_ids) != sorted(linked_not_ready_ids)
    ):
        findings.append(f"{prefix}_scorecard_not_ready_candidate_ids_mismatch")


def _gold_reviewer_handoff_apply_count_findings(
    payload: dict[str, Any],
    *,
    base_path: Path | None = None,
) -> list[str]:
    findings: list[str] = []
    package_counts: dict[str, int] = {}
    for field_name in (
        "result_count",
        "curation_ready_count",
        "not_ready_count",
        "ready_to_stage_count",
        "remaining_task_count",
    ):
        if field_name not in payload:
            continue
        value = _non_negative_int_payload_value(payload, field_name)
        if value is None:
            findings.append(f"gold_reviewer_handoff_apply_{field_name}_invalid")
            continue
        package_counts[field_name] = value

    result_count = package_counts.get("result_count")
    curation_ready_count = package_counts.get("curation_ready_count")
    not_ready_count = package_counts.get("not_ready_count")
    ready_to_stage_count = package_counts.get("ready_to_stage_count")
    remaining_task_count = package_counts.get("remaining_task_count")
    if (
        result_count is not None
        and curation_ready_count is not None
        and not_ready_count is not None
        and curation_ready_count + not_ready_count != result_count
    ):
        findings.append("gold_reviewer_handoff_apply_readiness_count_mismatch")
    if (
        ready_to_stage_count is not None
        and curation_ready_count is not None
        and ready_to_stage_count > curation_ready_count
    ):
        findings.append("gold_reviewer_handoff_apply_ready_to_stage_count_mismatch")
    findings.extend(
        _gold_reviewer_handoff_apply_linked_handoff_package_findings(
            payload,
            result_count=result_count,
            base_path=base_path,
        )
    )

    manifest = payload.get("patch_result_manifest")
    if isinstance(manifest, dict):
        manifest_result_count = _optional_non_negative_int_payload_value(manifest, "result_count")
        if manifest_result_count == "invalid":
            findings.append("gold_reviewer_handoff_apply_manifest_result_count_invalid")
        elif (
            isinstance(manifest_result_count, int)
            and result_count is not None
            and manifest_result_count != result_count
        ):
            findings.append("gold_reviewer_handoff_apply_manifest_result_count_mismatch")

        edited_count = _optional_non_negative_int_payload_value(manifest, "edited_result_count")
        unedited_count = _optional_non_negative_int_payload_value(manifest, "unedited_result_count")
        if edited_count == "invalid":
            findings.append("gold_reviewer_handoff_apply_edited_result_count_invalid")
        if unedited_count == "invalid":
            findings.append("gold_reviewer_handoff_apply_unedited_result_count_invalid")
        if (
            isinstance(edited_count, int)
            and isinstance(unedited_count, int)
            and result_count is not None
            and edited_count + unedited_count != result_count
        ):
            findings.append("gold_reviewer_handoff_apply_edit_count_mismatch")

        for field_name in ("curation_ready_count", "not_ready_count"):
            manifest_value = _optional_non_negative_int_payload_value(manifest, field_name)
            if manifest_value == "invalid":
                findings.append(f"gold_reviewer_handoff_apply_manifest_{field_name}_invalid")
            elif (
                isinstance(manifest_value, int)
                and field_name in package_counts
                and manifest_value != package_counts[field_name]
            ):
                findings.append(f"gold_reviewer_handoff_apply_manifest_{field_name}_mismatch")
    findings.extend(
        _gold_reviewer_handoff_apply_linked_patch_result_manifest_findings(
            payload,
            manifest,
            package_counts=package_counts,
            base_path=base_path,
        )
    )

    progress_report = payload.get("curation_progress_report")
    findings.extend(
        _gold_reviewer_handoff_apply_linked_progress_report_findings(
            payload,
            progress_report,
            package_counts=package_counts,
            base_path=base_path,
        )
    )

    curation_task_export = payload.get("curation_task_export")
    if isinstance(curation_task_export, dict):
        task_count = _optional_non_negative_int_payload_value(curation_task_export, "open_task_count")
        if task_count == "invalid":
            findings.append("gold_reviewer_handoff_apply_task_export_open_task_count_invalid")
        elif (
            isinstance(task_count, int)
            and remaining_task_count is not None
            and task_count != remaining_task_count
        ):
            findings.append("gold_reviewer_handoff_apply_remaining_task_count_mismatch")
    findings.extend(
        _gold_reviewer_handoff_linked_task_export_findings(
            payload,
            curation_task_export,
            expected_open_task_count=remaining_task_count if isinstance(remaining_task_count, int) else None,
            base_path=base_path,
            finding_prefix="gold_reviewer_handoff_apply_linked_task_export_",
        )
    )
    return findings


def _gold_reviewer_handoff_apply_linked_handoff_package_findings(
    payload: dict[str, Any],
    *,
    result_count: int | None = None,
    base_path: Path | None = None,
) -> list[str]:
    findings: set[str] = set()
    if base_path is None:
        return []
    prefix = "gold_reviewer_handoff_apply_linked_handoff_package_"
    raw_handoff_package_path = payload.get("reviewer_handoff_package_path")
    if not isinstance(raw_handoff_package_path, str) or not raw_handoff_package_path.strip():
        if "reviewer_handoff_package_path" in payload:
            findings.add(f"{prefix}path_invalid")
        return sorted(findings)
    try:
        linked_package_path = _resolve_related_review_path(raw_handoff_package_path, base_path=base_path)
        linked_package = _load_json_object(linked_package_path)
    except (OSError, ValueError, json.JSONDecodeError, RuntimeError):
        findings.add(f"{prefix}load_failed")
        return sorted(findings)
    if linked_package.get("schema_version") != "paper_understanding_gold_reviewer_handoff_package.v1":
        findings.add(f"{prefix}schema_version_invalid")
        return sorted(findings)
    findings.update(
        _prefixed_findings(
            _gold_reviewer_handoff_package_count_findings(linked_package, base_path=linked_package_path),
            source_prefix="gold_reviewer_handoff_",
            target_prefix=prefix,
        )
    )
    linked_draft_count = _optional_non_negative_int_payload_value(linked_package, "draft_count")
    if linked_draft_count == "invalid":
        findings.add(f"{prefix}draft_count_invalid")
    elif isinstance(linked_draft_count, int) and result_count is not None and linked_draft_count != result_count:
        findings.add(f"{prefix}draft_count_mismatch")
    return sorted(findings)


def _gold_reviewer_handoff_apply_linked_patch_result_manifest_findings(
    payload: dict[str, Any],
    embedded_manifest: Any,
    *,
    package_counts: dict[str, int],
    base_path: Path | None = None,
) -> list[str]:
    findings: set[str] = set()
    if base_path is None:
        return []
    prefix = "gold_reviewer_handoff_apply_linked_patch_result_manifest_"
    raw_manifest_path = payload.get("patch_result_manifest_path")
    if not isinstance(raw_manifest_path, str) or not raw_manifest_path.strip():
        if "patch_result_manifest_path" in payload:
            findings.add(f"{prefix}path_invalid")
        return sorted(findings)
    try:
        linked_manifest = _load_json_object(
            _resolve_related_review_path(raw_manifest_path, base_path=base_path)
        )
    except (OSError, ValueError, json.JSONDecodeError, RuntimeError):
        findings.add(f"{prefix}load_failed")
        return sorted(findings)
    if linked_manifest.get("schema_version") != "paper_understanding_gold_candidate_draft_patch_result_manifest.v1":
        findings.add(f"{prefix}schema_version_invalid")
        return sorted(findings)
    if (
        isinstance(embedded_manifest, dict)
        and embedded_manifest.get("schema_version") == "paper_understanding_gold_candidate_draft_patch_result_manifest.v1"
        and linked_manifest != embedded_manifest
    ):
        findings.add(f"{prefix}payload_mismatch")

    linked_counts: dict[str, int] = {}
    for field_name in (
        "result_count",
        "curation_ready_count",
        "not_ready_count",
        "edited_result_count",
        "unedited_result_count",
    ):
        linked_value = _optional_non_negative_int_payload_value(linked_manifest, field_name)
        if linked_value == "invalid":
            findings.add(f"{prefix}{field_name}_invalid")
        elif isinstance(linked_value, int):
            linked_counts[field_name] = linked_value
            if field_name in package_counts and linked_value != package_counts[field_name]:
                findings.add(f"{prefix}{field_name}_mismatch")

    linked_result_count = linked_counts.get("result_count")
    linked_curation_ready_count = linked_counts.get("curation_ready_count")
    linked_not_ready_count = linked_counts.get("not_ready_count")
    if (
        linked_result_count is not None
        and linked_curation_ready_count is not None
        and linked_not_ready_count is not None
        and linked_curation_ready_count + linked_not_ready_count != linked_result_count
    ):
        findings.add(f"{prefix}readiness_count_mismatch")
    linked_edited_count = linked_counts.get("edited_result_count")
    linked_unedited_count = linked_counts.get("unedited_result_count")
    if (
        linked_result_count is not None
        and linked_edited_count is not None
        and linked_unedited_count is not None
        and linked_edited_count + linked_unedited_count != linked_result_count
    ):
        findings.add(f"{prefix}edit_count_mismatch")

    patch_result_paths = linked_manifest.get("patch_result_paths")
    if isinstance(patch_result_paths, list):
        if linked_result_count is not None and len(patch_result_paths) != linked_result_count:
            findings.add(f"{prefix}patch_result_paths_count_mismatch")
    elif "patch_result_paths" in linked_manifest:
        findings.add(f"{prefix}patch_result_paths_invalid")
    return sorted(findings)


def _gold_reviewer_handoff_apply_linked_progress_report_findings(
    payload: dict[str, Any],
    embedded_progress_report: Any,
    *,
    package_counts: dict[str, int],
    base_path: Path | None = None,
) -> list[str]:
    findings: set[str] = set()
    if base_path is None:
        return []
    prefix = "gold_reviewer_handoff_apply_linked_progress_report_"
    raw_progress_path = payload.get("curation_progress_report_path")
    if not isinstance(raw_progress_path, str) or not raw_progress_path.strip():
        if "curation_progress_report_path" in payload:
            findings.add(f"{prefix}path_invalid")
        return sorted(findings)
    try:
        linked_progress = _load_json_object(
            _resolve_related_review_path(raw_progress_path, base_path=base_path)
        )
    except (OSError, ValueError, json.JSONDecodeError, RuntimeError):
        findings.add(f"{prefix}load_failed")
        return sorted(findings)
    if linked_progress.get("schema_version") != "paper_understanding_gold_candidate_draft_curation_progress.v1":
        findings.add(f"{prefix}schema_version_invalid")
        return sorted(findings)
    if (
        isinstance(embedded_progress_report, dict)
        and embedded_progress_report.get("schema_version") == "paper_understanding_gold_candidate_draft_curation_progress.v1"
        and _payload_without_generated_at(linked_progress) != _payload_without_generated_at(embedded_progress_report)
    ):
        findings.add(f"{prefix}payload_mismatch")

    field_expectations = {
        "draft_count": package_counts.get("result_count"),
        "ready_to_stage_count": package_counts.get("ready_to_stage_count"),
        "remaining_task_count": package_counts.get("remaining_task_count"),
    }
    linked_counts: dict[str, int] = {}
    for field_name, expected_value in field_expectations.items():
        linked_value = _optional_non_negative_int_payload_value(linked_progress, field_name)
        if linked_value == "invalid":
            findings.add(f"{prefix}{field_name}_invalid")
        elif isinstance(linked_value, int):
            linked_counts[field_name] = linked_value
            if expected_value is not None and linked_value != expected_value:
                findings.add(f"{prefix}{field_name}_mismatch")

    curation_complete = linked_progress.get("curation_complete")
    if "curation_complete" in linked_progress and not isinstance(curation_complete, bool):
        findings.add(f"{prefix}curation_complete_invalid")
    remaining_task_count = linked_counts.get("remaining_task_count")
    if curation_complete is True and isinstance(remaining_task_count, int) and remaining_task_count != 0:
        findings.add(f"{prefix}complete_with_remaining_tasks")

    items = linked_progress.get("items")
    draft_count = linked_counts.get("draft_count")
    if isinstance(items, list):
        if isinstance(draft_count, int) and len(items) not in (0, draft_count):
            findings.add(f"{prefix}items_count_mismatch")
    elif "items" in linked_progress:
        findings.add(f"{prefix}items_invalid")
    return sorted(findings)


def _payload_without_generated_at(payload: dict[str, Any]) -> dict[str, Any]:
    return {key: value for key, value in payload.items() if key != "generated_at"}


def _gold_release_readiness_count_findings(payload: dict[str, Any]) -> list[str]:
    findings: list[str] = []
    counts: dict[str, int] = {}
    for field_name in (
        "manifest_count",
        "item_count",
        "ready_count",
        "invalid_count",
        "min_ready_per_split",
    ):
        value = _optional_non_negative_int_payload_value(payload, field_name)
        if value == "invalid":
            findings.append(f"gold_release_readiness_{field_name}_invalid")
        elif isinstance(value, int):
            counts[field_name] = value

    release_ready = payload.get("release_ready")
    if "release_ready" in payload and not isinstance(release_ready, bool):
        findings.append("gold_release_readiness_release_ready_invalid")

    split_summaries = payload.get("split_summaries")
    summary_splits: set[str] = set()
    summary_goldset_ids: set[str] = set()
    summary_totals = {
        "item_count": 0,
        "ready_count": 0,
        "invalid_count": 0,
    }
    summary_counts_valid = True
    has_nonpassing_split = False
    if isinstance(split_summaries, list):
        if "manifest_count" in counts and len(split_summaries) != counts["manifest_count"]:
            findings.append("gold_release_readiness_manifest_count_mismatch")
        for raw_summary in split_summaries:
            if not isinstance(raw_summary, dict):
                summary_counts_valid = False
                has_nonpassing_split = True
                continue
            status = str(raw_summary.get("status") or "").strip()
            if status != "pass":
                has_nonpassing_split = True
            split = str(raw_summary.get("goldset_split") or "").strip()
            if split:
                summary_splits.add(split)
            goldset_id = str(raw_summary.get("goldset_id") or "").strip()
            if goldset_id:
                summary_goldset_ids.add(goldset_id)
            for field_name in summary_totals:
                value = _optional_non_negative_int_payload_value(raw_summary, field_name)
                if value == "invalid" or value is None:
                    summary_counts_valid = False
                    continue
                summary_totals[field_name] += value
            paper_ids = raw_summary.get("paper_ids")
            item_count = _optional_non_negative_int_payload_value(raw_summary, "item_count")
            if isinstance(paper_ids, list) and isinstance(item_count, int) and len(paper_ids) != item_count:
                summary_counts_valid = False
        if not summary_counts_valid:
            findings.append("gold_release_readiness_split_summary_count_invalid")
        else:
            for field_name, expected_value in summary_totals.items():
                if field_name in counts and counts[field_name] != expected_value:
                    findings.append(f"gold_release_readiness_{field_name}_mismatch")
    elif "split_summaries" in payload:
        findings.append("gold_release_readiness_split_summaries_invalid")

    goldset_ids = payload.get("goldset_ids")
    if isinstance(goldset_ids, list) and summary_goldset_ids:
        observed_goldset_ids = {str(item or "").strip() for item in goldset_ids if str(item or "").strip()}
        if observed_goldset_ids != summary_goldset_ids:
            findings.append("gold_release_readiness_goldset_ids_mismatch")
    elif "goldset_ids" in payload and goldset_ids is not None:
        findings.append("gold_release_readiness_goldset_ids_invalid")

    if release_ready is True:
        if counts.get("invalid_count", 0) != 0:
            findings.append("gold_release_readiness_ready_with_invalid_items")
        for field_name in ("blockers", "missing_splits", "underfilled_splits", "duplicate_paper_ids"):
            value = payload.get(field_name)
            if isinstance(value, list) and value:
                findings.append(f"gold_release_readiness_ready_with_{field_name}")
            elif field_name in payload and not isinstance(value, list):
                findings.append(f"gold_release_readiness_{field_name}_invalid")
        required_splits = payload.get("required_splits")
        if isinstance(required_splits, list) and isinstance(split_summaries, list):
            required_split_set = {str(item or "").strip() for item in required_splits if str(item or "").strip()}
            if required_split_set - summary_splits:
                findings.append("gold_release_readiness_ready_missing_required_split")
            if counts.get("ready_count", 0) < len(required_split_set):
                findings.append("gold_release_readiness_ready_count_under_required_splits")
        elif "required_splits" in payload:
            findings.append("gold_release_readiness_required_splits_invalid")
        if has_nonpassing_split:
            findings.append("gold_release_readiness_ready_with_nonpassing_split")
    return findings


def _gold_release_split_plan_count_findings(payload: dict[str, Any]) -> list[str]:
    findings: list[str] = []
    ready_input_count = _optional_non_negative_int_payload_value(payload, "ready_input_count")
    invalid_input_count = _optional_non_negative_int_payload_value(payload, "invalid_input_count")
    min_ready_per_split = _optional_non_negative_int_payload_value(payload, "min_ready_per_split")
    if ready_input_count == "invalid":
        findings.append("gold_release_split_plan_ready_input_count_invalid")
    if invalid_input_count == "invalid":
        findings.append("gold_release_split_plan_invalid_input_count_invalid")
    if min_ready_per_split == "invalid":
        findings.append("gold_release_split_plan_min_ready_per_split_invalid")

    release_ready_candidate = payload.get("release_ready_candidate")
    if "release_ready_candidate" in payload and not isinstance(release_ready_candidate, bool):
        findings.append("gold_release_split_plan_candidate_status_invalid")
    if release_ready_candidate is True and isinstance(invalid_input_count, int) and invalid_input_count != 0:
        findings.append("gold_release_split_plan_ready_candidate_with_invalid_inputs")

    split_names = payload.get("split_names")
    split_name_set: set[str] = set()
    if isinstance(split_names, list):
        split_name_set = {str(item or "").strip() for item in split_names if str(item or "").strip()}
    elif "split_names" in payload:
        findings.append("gold_release_split_plan_split_names_invalid")

    split_manifests = payload.get("split_manifests")
    if isinstance(split_manifests, list) and split_name_set and len(split_manifests) != len(split_name_set):
        findings.append("gold_release_split_plan_split_manifest_count_mismatch")
    elif "split_manifests" in payload and not isinstance(split_manifests, list):
        findings.append("gold_release_split_plan_split_manifests_invalid")

    split_items = payload.get("split_items")
    if not isinstance(split_items, list):
        if "split_items" in payload:
            findings.append("gold_release_split_plan_split_items_invalid")
        return findings

    if split_name_set and len(split_items) != len(split_name_set):
        findings.append("gold_release_split_plan_split_name_count_mismatch")
    if isinstance(split_manifests, list) and len(split_manifests) != len(split_items):
        findings.append("gold_release_split_plan_split_manifest_item_count_mismatch")

    staged_total = 0
    staged_counts_valid = True
    underfilled_candidate_split = False
    for raw_item in split_items:
        if not isinstance(raw_item, dict):
            staged_counts_valid = False
            underfilled_candidate_split = True
            continue
        staged_count = _optional_non_negative_int_payload_value(raw_item, "staged_count")
        if staged_count == "invalid" or staged_count is None:
            staged_counts_valid = False
            underfilled_candidate_split = True
            continue
        staged_total += staged_count
        paper_ids = raw_item.get("paper_ids")
        if isinstance(paper_ids, list) and len(paper_ids) != staged_count:
            findings.append("gold_release_split_plan_split_item_staged_count_mismatch")
        if (
            release_ready_candidate is True
            and isinstance(min_ready_per_split, int)
            and staged_count < min_ready_per_split
        ):
            underfilled_candidate_split = True
    if not staged_counts_valid:
        findings.append("gold_release_split_plan_split_item_count_invalid")
    elif isinstance(ready_input_count, int) and staged_total != ready_input_count:
        findings.append("gold_release_split_plan_ready_input_count_mismatch")
    if underfilled_candidate_split and release_ready_candidate is True:
        findings.append("gold_release_split_plan_underfilled_candidate_split")
    return findings


def _gold_release_package_count_findings(
    payload: dict[str, Any],
    *,
    base_path: Path | None = None,
) -> list[str]:
    findings: list[str] = []
    manifest_paths = payload.get("manifest_paths")
    manifest_path_count: int | None = None
    if isinstance(manifest_paths, list):
        manifest_path_count = len(manifest_paths)
    elif "manifest_paths" in payload:
        findings.append("gold_release_package_manifest_paths_invalid")

    source_split_manifests = payload.get("source_split_manifests")
    if isinstance(source_split_manifests, list):
        if (
            source_split_manifests
            and manifest_path_count is not None
            and len(source_split_manifests) != manifest_path_count
        ):
            findings.append("gold_release_package_source_manifest_count_mismatch")
    elif "source_split_manifests" in payload:
        findings.append("gold_release_package_source_split_manifests_invalid")

    release_readiness = payload.get("release_readiness")
    if isinstance(release_readiness, dict):
        readiness_manifest_count = _optional_non_negative_int_payload_value(release_readiness, "manifest_count")
        if readiness_manifest_count == "invalid":
            findings.append("gold_release_package_readiness_manifest_count_invalid")
        elif (
            isinstance(readiness_manifest_count, int)
            and manifest_path_count is not None
            and readiness_manifest_count != manifest_path_count
        ):
            findings.append("gold_release_package_readiness_manifest_count_mismatch")
        findings.extend(_prefixed_findings(
            _gold_release_readiness_count_findings(release_readiness),
            source_prefix="gold_release_readiness_",
            target_prefix="gold_release_package_embedded_readiness_",
        ))
    elif "release_readiness" in payload:
        findings.append("gold_release_package_embedded_readiness_invalid")
    findings.extend(
        _gold_release_package_linked_readiness_findings(
            payload,
            manifest_paths,
            release_readiness,
            base_path=base_path,
        )
    )
    return findings


def _gold_release_package_linked_readiness_findings(
    payload: dict[str, Any],
    manifest_paths: Any,
    embedded_readiness: Any,
    *,
    base_path: Path | None = None,
) -> list[str]:
    findings: set[str] = set()
    if base_path is None:
        return []
    raw_readiness_path = payload.get("release_readiness_report_path")
    if not isinstance(raw_readiness_path, str) or not raw_readiness_path.strip():
        if "release_readiness_report_path" in payload:
            findings.add("gold_release_package_linked_readiness_path_invalid")
        return sorted(findings)
    try:
        linked_readiness_path = _resolve_related_review_path(raw_readiness_path, base_path=base_path)
        linked_readiness = _load_json_object(linked_readiness_path)
    except (OSError, ValueError, json.JSONDecodeError, RuntimeError):
        findings.add("gold_release_package_linked_readiness_load_failed")
        return sorted(findings)
    if linked_readiness.get("schema_version") != "paper_understanding_gold_release_readiness.v1":
        findings.add("gold_release_package_linked_readiness_schema_version_invalid")
        return sorted(findings)

    findings.update(
        _prefixed_findings(
            _gold_release_readiness_count_findings(linked_readiness),
            source_prefix="gold_release_readiness_",
            target_prefix="gold_release_package_linked_readiness_",
        )
    )
    if isinstance(embedded_readiness, dict) and linked_readiness != embedded_readiness:
        findings.add("gold_release_package_linked_readiness_payload_mismatch")

    if isinstance(manifest_paths, list) and all(isinstance(path, str) for path in manifest_paths):
        package_manifest_paths = {
            str(_resolve_related_review_path(path, base_path=base_path))
            for path in manifest_paths
            if path.strip()
        }
        linked_manifest_count = _optional_non_negative_int_payload_value(linked_readiness, "manifest_count")
        if isinstance(linked_manifest_count, int) and linked_manifest_count != len(package_manifest_paths):
            findings.add("gold_release_package_linked_readiness_manifest_count_mismatch")
        split_summaries = linked_readiness.get("split_summaries")
        readiness_manifest_paths: set[str] = set()
        readiness_manifest_paths_known = True
        if isinstance(split_summaries, list):
            for summary in split_summaries:
                if not isinstance(summary, dict):
                    readiness_manifest_paths_known = False
                    continue
                raw_manifest_path = summary.get("manifest_path")
                if not isinstance(raw_manifest_path, str) or not raw_manifest_path.strip():
                    readiness_manifest_paths_known = False
                    continue
                readiness_manifest_paths.add(
                    str(_resolve_related_review_path(raw_manifest_path, base_path=linked_readiness_path))
                )
            if readiness_manifest_paths_known and package_manifest_paths != readiness_manifest_paths:
                findings.add("gold_release_package_linked_readiness_manifest_paths_mismatch")
            elif not readiness_manifest_paths_known:
                findings.add("gold_release_package_linked_readiness_manifest_paths_invalid")
    return sorted(findings)


def _gold_curation_task_export_count_findings(payload: dict[str, Any]) -> list[str]:
    findings: list[str] = []
    open_task_count = _optional_non_negative_int_payload_value(payload, "open_task_count")
    if open_task_count == "invalid":
        findings.append("gold_curation_task_export_count_invalid")
    paper_count = _optional_non_negative_int_payload_value(payload, "paper_count")
    if paper_count == "invalid":
        findings.append("gold_curation_task_export_paper_count_invalid")

    items = payload.get("items")
    if not isinstance(items, list):
        if "items" in payload:
            findings.append("gold_curation_task_export_items_invalid")
        return findings
    if isinstance(open_task_count, int) and len(items) != open_task_count:
        findings.append("gold_curation_task_export_count_mismatch")

    item_paper_ids: set[str] = set()
    status_by_paper_id: dict[str, str] = {}
    expected_reason_code_counts: dict[str, int] = {}
    expected_target_field_counts: dict[str, int] = {}
    expected_curation_stage_counts: dict[str, int] = {}
    expected_review_priority_counts: dict[str, int] = {}
    invalid_item = False
    for raw_item in items:
        if not isinstance(raw_item, dict):
            invalid_item = True
            continue
        paper_id = str(raw_item.get("paper_id") or "").strip()
        task_id = str(raw_item.get("task_id") or "").strip()
        status = str(raw_item.get("status") or "").strip()
        reason_code = str(raw_item.get("reason_code") or "").strip()
        target_field = str(raw_item.get("target_field") or "").strip()
        if not paper_id or not task_id or not status or not reason_code or not target_field:
            invalid_item = True
        if paper_id:
            item_paper_ids.add(paper_id)
            previous_status = status_by_paper_id.get(paper_id)
            if previous_status is not None and previous_status != status:
                invalid_item = True
            elif status:
                status_by_paper_id[paper_id] = status
        _increment_count(expected_reason_code_counts, reason_code)
        _increment_count(expected_target_field_counts, target_field)
        curation_stage = str(raw_item.get("curation_stage") or "unspecified").strip() or "unspecified"
        _increment_count(expected_curation_stage_counts, curation_stage)
        raw_priority = raw_item.get("review_priority", 100)
        try:
            priority = int(raw_priority)
        except (TypeError, ValueError):
            invalid_item = True
            priority = 100
        _increment_count(expected_review_priority_counts, str(priority))
    if invalid_item:
        findings.append("gold_curation_task_export_item_invalid")
    if isinstance(paper_count, int) and len(item_paper_ids) != paper_count:
        findings.append("gold_curation_task_export_paper_count_mismatch")
    expected_status_counts: dict[str, int] = {}
    for status in status_by_paper_id.values():
        _increment_count(expected_status_counts, status)
    for field_name, expected_counts in (
        ("status_counts", expected_status_counts),
        ("reason_code_counts", expected_reason_code_counts),
        ("target_field_counts", expected_target_field_counts),
        ("curation_stage_counts", expected_curation_stage_counts),
        ("review_priority_counts", expected_review_priority_counts),
    ):
        observed_counts = _normalized_non_negative_count_map(payload.get(field_name))
        if observed_counts is None:
            if field_name in payload:
                findings.append(f"gold_curation_task_export_{field_name}_invalid")
            continue
        if observed_counts != expected_counts:
            findings.append(f"gold_curation_task_export_{field_name}_mismatch")
    return findings


def _gold_reviewer_handoff_package_count_findings(
    payload: dict[str, Any],
    *,
    base_path: Path | None = None,
) -> list[str]:
    findings: list[str] = []
    draft_count = _optional_non_negative_int_payload_value(payload, "draft_count")
    open_task_count = _optional_non_negative_int_payload_value(payload, "open_task_count")
    if draft_count == "invalid":
        findings.append("gold_reviewer_handoff_draft_count_invalid")
    if open_task_count == "invalid":
        findings.append("gold_reviewer_handoff_task_count_invalid")
    curation_ready = payload.get("curation_ready")
    if "curation_ready" in payload and not isinstance(curation_ready, bool):
        findings.append("gold_reviewer_handoff_curation_ready_invalid")
    if curation_ready is True and isinstance(open_task_count, int) and open_task_count != 0:
        findings.append("gold_reviewer_handoff_ready_with_open_tasks")

    curation_package = payload.get("curation_package")
    if isinstance(curation_package, dict):
        embedded_ready = curation_package.get("curation_ready")
        if isinstance(embedded_ready, bool) and isinstance(curation_ready, bool):
            expected_ready = embedded_ready and open_task_count == 0
            if curation_ready != expected_ready:
                findings.append("gold_reviewer_handoff_curation_ready_mismatch")
        draft_manifest = curation_package.get("draft_manifest")
        if isinstance(draft_manifest, dict):
            manifest_draft_count = _optional_non_negative_int_payload_value(draft_manifest, "draft_count")
            if manifest_draft_count == "invalid":
                findings.append("gold_reviewer_handoff_curation_package_manifest_draft_count_invalid")
            elif (
                isinstance(manifest_draft_count, int)
                and isinstance(draft_count, int)
                and manifest_draft_count != draft_count
            ):
                findings.append("gold_reviewer_handoff_curation_package_manifest_draft_count_mismatch")
        curation_report = curation_package.get("curation_report")
        if isinstance(curation_report, dict):
            report_draft_count = _optional_non_negative_int_payload_value(curation_report, "draft_count")
            if report_draft_count == "invalid":
                findings.append("gold_reviewer_handoff_curation_package_report_draft_count_invalid")
            elif (
                isinstance(report_draft_count, int)
                and isinstance(draft_count, int)
                and report_draft_count != draft_count
            ):
                findings.append("gold_reviewer_handoff_curation_package_report_draft_count_mismatch")
    elif "curation_package" in payload:
        findings.append("gold_reviewer_handoff_curation_package_invalid")

    patch_template_manifest = payload.get("patch_template_manifest")
    if isinstance(patch_template_manifest, dict):
        template_count = _optional_non_negative_int_payload_value(patch_template_manifest, "template_count")
        if template_count == "invalid":
            findings.append("gold_reviewer_handoff_template_count_invalid")
        elif isinstance(template_count, int) and isinstance(draft_count, int) and template_count != draft_count:
            findings.append("gold_reviewer_handoff_template_count_mismatch")
        template_open_task_count = _optional_non_negative_int_payload_value(
            patch_template_manifest,
            "open_task_count",
        )
        if template_open_task_count == "invalid":
            findings.append("gold_reviewer_handoff_template_open_task_count_invalid")
        elif (
            isinstance(template_open_task_count, int)
            and isinstance(open_task_count, int)
            and template_open_task_count != open_task_count
        ):
            findings.append("gold_reviewer_handoff_template_open_task_count_mismatch")
        template_paths = patch_template_manifest.get("template_paths")
        if isinstance(template_paths, list) and isinstance(template_count, int) and len(template_paths) != template_count:
            findings.append("gold_reviewer_handoff_template_paths_count_mismatch")
    elif "patch_template_manifest" in payload:
        findings.append("gold_reviewer_handoff_patch_template_manifest_invalid")

    progress_report = payload.get("curation_progress_report")
    if isinstance(progress_report, dict):
        progress_draft_count = _optional_non_negative_int_payload_value(progress_report, "draft_count")
        if progress_draft_count == "invalid":
            findings.append("gold_reviewer_handoff_progress_draft_count_invalid")
        elif (
            isinstance(progress_draft_count, int)
            and isinstance(draft_count, int)
            and progress_draft_count != draft_count
        ):
            findings.append("gold_reviewer_handoff_progress_draft_count_mismatch")
        progress_remaining = _optional_non_negative_int_payload_value(progress_report, "remaining_task_count")
        if progress_remaining == "invalid":
            findings.append("gold_reviewer_handoff_progress_remaining_task_count_invalid")
        elif (
            isinstance(progress_remaining, int)
            and isinstance(open_task_count, int)
            and progress_remaining != open_task_count
        ):
            findings.append("gold_reviewer_handoff_progress_remaining_task_count_mismatch")
        progress_complete = progress_report.get("curation_complete")
        if isinstance(progress_complete, bool) and progress_complete and isinstance(open_task_count, int) and open_task_count != 0:
            findings.append("gold_reviewer_handoff_progress_complete_with_open_tasks")
    elif "curation_progress_report" in payload:
        findings.append("gold_reviewer_handoff_curation_progress_report_invalid")

    task_export = payload.get("curation_task_export")
    if isinstance(task_export, dict):
        task_export_paper_count = _optional_non_negative_int_payload_value(task_export, "paper_count")
        if task_export_paper_count == "invalid":
            findings.append("gold_reviewer_handoff_task_export_paper_count_invalid")
        elif (
            isinstance(task_export_paper_count, int)
            and isinstance(draft_count, int)
            and task_export_paper_count != draft_count
        ):
            findings.append("gold_reviewer_handoff_task_export_paper_count_mismatch")
        task_export_open_count = _optional_non_negative_int_payload_value(task_export, "open_task_count")
        if task_export_open_count == "invalid":
            findings.append("gold_reviewer_handoff_task_export_open_task_count_invalid")
        elif (
            isinstance(task_export_open_count, int)
            and isinstance(open_task_count, int)
            and task_export_open_count != open_task_count
        ):
            findings.append("gold_reviewer_handoff_task_export_open_task_count_mismatch")
        findings.extend(_prefixed_findings(
            _gold_curation_task_export_count_findings(task_export),
            source_prefix="gold_curation_task_export_",
            target_prefix="gold_reviewer_handoff_task_export_",
        ))
    elif "curation_task_export" in payload:
        findings.append("gold_reviewer_handoff_curation_task_export_invalid")
    findings.extend(
        _gold_reviewer_handoff_linked_task_export_findings(
            payload,
            task_export,
            expected_paper_count=draft_count if isinstance(draft_count, int) else None,
            expected_open_task_count=open_task_count if isinstance(open_task_count, int) else None,
            base_path=base_path,
            finding_prefix="gold_reviewer_handoff_linked_task_export_",
        )
    )
    return findings


def _gold_reviewer_handoff_linked_task_export_findings(
    payload: dict[str, Any],
    embedded_task_export: Any,
    *,
    expected_paper_count: int | None = None,
    expected_open_task_count: int | None = None,
    base_path: Path | None = None,
    finding_prefix: str,
) -> list[str]:
    findings: set[str] = set()
    if base_path is None:
        return []
    raw_task_export_path = payload.get("curation_task_export_path")
    if not isinstance(raw_task_export_path, str) or not raw_task_export_path.strip():
        if "curation_task_export_path" in payload:
            findings.add(f"{finding_prefix}path_invalid")
        return sorted(findings)
    try:
        linked_task_export = _load_json_object(
            _resolve_related_review_path(raw_task_export_path, base_path=base_path)
        )
    except (OSError, ValueError, json.JSONDecodeError, RuntimeError):
        findings.add(f"{finding_prefix}load_failed")
        return sorted(findings)
    if linked_task_export.get("schema_version") != "paper_understanding_gold_curation_task_export.v1":
        findings.add(f"{finding_prefix}schema_version_invalid")
        return sorted(findings)

    if (
        isinstance(embedded_task_export, dict)
        and embedded_task_export.get("schema_version") == "paper_understanding_gold_curation_task_export.v1"
        and linked_task_export != embedded_task_export
    ):
        findings.add(f"{finding_prefix}payload_mismatch")
    linked_paper_count = _optional_non_negative_int_payload_value(linked_task_export, "paper_count")
    if linked_paper_count == "invalid":
        findings.add(f"{finding_prefix}paper_count_invalid")
    elif (
        isinstance(linked_paper_count, int)
        and expected_paper_count is not None
        and linked_paper_count != expected_paper_count
    ):
        findings.add(f"{finding_prefix}paper_count_mismatch")
    linked_open_count = _optional_non_negative_int_payload_value(linked_task_export, "open_task_count")
    if linked_open_count == "invalid":
        findings.add(f"{finding_prefix}open_task_count_invalid")
    elif (
        isinstance(linked_open_count, int)
        and expected_open_task_count is not None
        and linked_open_count != expected_open_task_count
    ):
        findings.add(f"{finding_prefix}open_task_count_mismatch")
    findings.update(
        _prefixed_findings(
            _gold_curation_task_export_count_findings(linked_task_export),
            source_prefix="gold_curation_task_export_",
            target_prefix=finding_prefix,
        )
    )
    return sorted(findings)


def _prefixed_findings(findings: list[str], *, source_prefix: str, target_prefix: str) -> list[str]:
    return [
        f"{target_prefix}{finding.removeprefix(source_prefix)}"
        if finding.startswith(source_prefix)
        else finding
        for finding in findings
    ]


def _increment_count(counts: dict[str, int], key: str) -> None:
    if not key:
        return
    counts[key] = counts.get(key, 0) + 1


def _normalized_non_negative_count_map(raw_value: Any) -> dict[str, int] | None:
    if not isinstance(raw_value, dict):
        return None
    counts: dict[str, int] = {}
    for raw_key, raw_count in raw_value.items():
        key = str(raw_key or "").strip()
        if not key:
            return None
        value = _coerce_non_negative_int(raw_count)
        if value is None:
            return None
        if value > 0:
            counts[key] = value
    return counts


def _gold_reviewer_handoff_stage_count_findings(
    payload: dict[str, Any],
    *,
    base_path: Path | None = None,
) -> list[str]:
    findings: list[str] = []
    staged_count = _optional_non_negative_int_payload_value(payload, "staged_count")
    remaining_task_count = _optional_non_negative_int_payload_value(payload, "remaining_task_count")
    if staged_count == "invalid":
        findings.append("gold_reviewer_handoff_stage_count_invalid")
    if remaining_task_count == "invalid":
        findings.append("gold_reviewer_handoff_stage_remaining_task_count_invalid")
    curation_complete = payload.get("curation_complete")
    if "curation_complete" in payload and not isinstance(curation_complete, bool):
        findings.append("gold_reviewer_handoff_stage_completion_invalid")
    if curation_complete is True:
        if staged_count == 0:
            findings.append("gold_reviewer_handoff_stage_complete_without_staged_records")
        if isinstance(remaining_task_count, int) and remaining_task_count != 0:
            findings.append("gold_reviewer_handoff_stage_complete_with_remaining_tasks")
    findings.extend(
        _gold_reviewer_handoff_stage_linked_apply_package_findings(
            payload,
            staged_count=staged_count if isinstance(staged_count, int) else None,
            remaining_task_count=remaining_task_count if isinstance(remaining_task_count, int) else None,
            curation_complete=curation_complete if isinstance(curation_complete, bool) else None,
            base_path=base_path,
        )
    )
    findings.extend(
        _gold_reviewer_handoff_stage_linked_handoff_package_findings(
            payload,
            staged_count=staged_count if isinstance(staged_count, int) else None,
            base_path=base_path,
        )
    )

    staging_manifest = payload.get("staging_manifest")
    if isinstance(staging_manifest, dict):
        manifest_staged_count = _optional_non_negative_int_payload_value(staging_manifest, "staged_count")
        if manifest_staged_count == "invalid":
            findings.append("gold_reviewer_handoff_stage_manifest_staged_count_invalid")
        elif (
            isinstance(manifest_staged_count, int)
            and isinstance(staged_count, int)
            and manifest_staged_count != staged_count
        ):
            findings.append("gold_reviewer_handoff_stage_manifest_staged_count_mismatch")
        staged_paths = staging_manifest.get("staged_paths")
        if isinstance(staged_paths, list) and isinstance(staged_count, int) and len(staged_paths) != staged_count:
            findings.append("gold_reviewer_handoff_stage_manifest_staged_paths_count_mismatch")
    findings.extend(
        _gold_reviewer_handoff_stage_linked_staging_manifest_findings(
            payload,
            staging_manifest,
            staged_count=staged_count if isinstance(staged_count, int) else None,
            base_path=base_path,
        )
    )

    progress_report = payload.get("curation_progress_report")
    if isinstance(progress_report, dict):
        progress_staged_count = _optional_non_negative_int_payload_value(progress_report, "staged_count")
        if progress_staged_count == "invalid":
            findings.append("gold_reviewer_handoff_stage_progress_staged_count_invalid")
        elif (
            isinstance(progress_staged_count, int)
            and isinstance(staged_count, int)
            and progress_staged_count != staged_count
        ):
            findings.append("gold_reviewer_handoff_stage_progress_staged_count_mismatch")
        progress_remaining = _optional_non_negative_int_payload_value(progress_report, "remaining_task_count")
        if progress_remaining == "invalid":
            findings.append("gold_reviewer_handoff_stage_progress_remaining_task_count_invalid")
        elif (
            isinstance(progress_remaining, int)
            and isinstance(remaining_task_count, int)
            and progress_remaining != remaining_task_count
        ):
            findings.append("gold_reviewer_handoff_stage_progress_remaining_task_count_mismatch")
        progress_complete = progress_report.get("curation_complete")
        if isinstance(progress_complete, bool) and isinstance(curation_complete, bool) and progress_complete != curation_complete:
            findings.append("gold_reviewer_handoff_stage_progress_completion_mismatch")
    findings.extend(
        _gold_reviewer_handoff_stage_linked_progress_report_findings(
            payload,
            progress_report,
            staged_count=staged_count if isinstance(staged_count, int) else None,
            remaining_task_count=remaining_task_count if isinstance(remaining_task_count, int) else None,
            curation_complete=curation_complete if isinstance(curation_complete, bool) else None,
            base_path=base_path,
        )
    )

    task_export = payload.get("curation_task_export")
    if isinstance(task_export, dict):
        task_count = _optional_non_negative_int_payload_value(task_export, "open_task_count")
        if task_count == "invalid":
            findings.append("gold_reviewer_handoff_stage_task_export_open_task_count_invalid")
        elif (
            isinstance(task_count, int)
            and isinstance(remaining_task_count, int)
            and task_count != remaining_task_count
        ):
            findings.append("gold_reviewer_handoff_stage_remaining_task_count_mismatch")
    findings.extend(
        _gold_reviewer_handoff_linked_task_export_findings(
            payload,
            task_export,
            expected_open_task_count=remaining_task_count if isinstance(remaining_task_count, int) else None,
            base_path=base_path,
            finding_prefix="gold_reviewer_handoff_stage_linked_task_export_",
        )
    )
    return findings


def _gold_reviewer_handoff_stage_linked_apply_package_findings(
    payload: dict[str, Any],
    *,
    staged_count: int | None = None,
    remaining_task_count: int | None = None,
    curation_complete: bool | None = None,
    base_path: Path | None = None,
) -> list[str]:
    findings: set[str] = set()
    if base_path is None:
        return []
    prefix = "gold_reviewer_handoff_stage_linked_apply_package_"
    raw_apply_package_path = payload.get("reviewer_handoff_apply_package_path")
    if not isinstance(raw_apply_package_path, str) or not raw_apply_package_path.strip():
        if "reviewer_handoff_apply_package_path" in payload:
            findings.add(f"{prefix}path_invalid")
        return sorted(findings)
    try:
        linked_apply_package = _load_json_object(
            _resolve_related_review_path(raw_apply_package_path, base_path=base_path)
        )
    except (OSError, ValueError, json.JSONDecodeError, RuntimeError):
        findings.add(f"{prefix}load_failed")
        return sorted(findings)
    if linked_apply_package.get("schema_version") != "paper_understanding_gold_reviewer_handoff_apply_package.v1":
        findings.add(f"{prefix}schema_version_invalid")
        return sorted(findings)

    result_count = _optional_non_negative_int_payload_value(linked_apply_package, "result_count")
    curation_ready_count = _optional_non_negative_int_payload_value(linked_apply_package, "curation_ready_count")
    not_ready_count = _optional_non_negative_int_payload_value(linked_apply_package, "not_ready_count")
    ready_to_stage_count = _optional_non_negative_int_payload_value(linked_apply_package, "ready_to_stage_count")
    linked_remaining_task_count = _optional_non_negative_int_payload_value(
        linked_apply_package,
        "remaining_task_count",
    )
    for field_name, value in (
        ("result_count", result_count),
        ("curation_ready_count", curation_ready_count),
        ("not_ready_count", not_ready_count),
        ("ready_to_stage_count", ready_to_stage_count),
        ("remaining_task_count", linked_remaining_task_count),
    ):
        if value == "invalid":
            findings.add(f"{prefix}{field_name}_invalid")
    if (
        isinstance(result_count, int)
        and isinstance(curation_ready_count, int)
        and isinstance(not_ready_count, int)
        and curation_ready_count + not_ready_count != result_count
    ):
        findings.add(f"{prefix}readiness_count_mismatch")
    if (
        isinstance(ready_to_stage_count, int)
        and isinstance(curation_ready_count, int)
        and ready_to_stage_count > curation_ready_count
    ):
        findings.add(f"{prefix}ready_to_stage_count_mismatch")
    if isinstance(ready_to_stage_count, int) and staged_count is not None and ready_to_stage_count < staged_count:
        findings.add(f"{prefix}ready_to_stage_count_mismatch")
    if curation_complete is True and isinstance(not_ready_count, int) and not_ready_count != 0:
        findings.add(f"{prefix}not_ready_count_mismatch")
    if (
        isinstance(linked_remaining_task_count, int)
        and remaining_task_count is not None
        and linked_remaining_task_count != remaining_task_count
    ):
        findings.add(f"{prefix}remaining_task_count_mismatch")
    return sorted(findings)


