def _gold_reviewer_handoff_release_prep_count_findings(
    payload: dict[str, Any],
    *,
    base_path: Path | None = None,
) -> list[str]:
    findings: list[str] = []
    staged_count = _optional_non_negative_int_payload_value(payload, "staged_count")
    split_count = _optional_non_negative_int_payload_value(payload, "split_count")
    if staged_count == "invalid":
        findings.append("gold_reviewer_handoff_release_prep_staged_count_invalid")
    if split_count == "invalid":
        findings.append("gold_reviewer_handoff_release_prep_split_count_invalid")
    release_ready_candidate = payload.get("release_ready_candidate")
    release_ready = payload.get("release_ready")
    if "release_ready_candidate" in payload and not isinstance(release_ready_candidate, bool):
        findings.append("gold_reviewer_handoff_release_prep_candidate_status_invalid")
    if "release_ready" in payload and not isinstance(release_ready, bool):
        findings.append("gold_reviewer_handoff_release_prep_release_status_invalid")
    if release_ready is True and release_ready_candidate is not True:
        findings.append("gold_reviewer_handoff_release_prep_ready_without_candidate")
    if release_ready is True and not isinstance(staged_count, int):
        findings.append("gold_reviewer_handoff_release_prep_ready_without_valid_staged_count")
    elif release_ready is True and staged_count == 0:
        findings.append("gold_reviewer_handoff_release_prep_ready_without_staged_records")

    split_plan = payload.get("split_plan")
    if isinstance(split_plan, dict):
        split_plan_ready = split_plan.get("release_ready_candidate")
        if isinstance(split_plan_ready, bool) and isinstance(release_ready_candidate, bool) and split_plan_ready != release_ready_candidate:
            findings.append("gold_reviewer_handoff_release_prep_split_plan_candidate_status_mismatch")
        ready_input_count = _optional_non_negative_int_payload_value(split_plan, "ready_input_count")
        if ready_input_count == "invalid":
            findings.append("gold_reviewer_handoff_release_prep_split_plan_ready_input_count_invalid")
        elif (
            isinstance(ready_input_count, int)
            and isinstance(staged_count, int)
            and ready_input_count != staged_count
        ):
            findings.append("gold_reviewer_handoff_release_prep_split_plan_ready_input_count_mismatch")
        split_items = split_plan.get("split_items")
        if isinstance(split_items, list):
            if isinstance(split_count, int) and len(split_items) != split_count:
                findings.append("gold_reviewer_handoff_release_prep_split_item_count_mismatch")
            split_item_staged_total = 0
            staged_total_valid = True
            for raw_item in split_items:
                if not isinstance(raw_item, dict):
                    staged_total_valid = False
                    continue
                item_staged_count = _optional_non_negative_int_payload_value(raw_item, "staged_count")
                if item_staged_count == "invalid" or item_staged_count is None:
                    staged_total_valid = False
                    continue
                split_item_staged_total += item_staged_count
            if staged_total_valid and isinstance(staged_count, int) and split_item_staged_total != staged_count:
                findings.append("gold_reviewer_handoff_release_prep_split_item_staged_count_mismatch")
    elif "split_plan" in payload:
        findings.append("gold_reviewer_handoff_release_prep_split_plan_invalid")
    findings.extend(
        _gold_reviewer_handoff_release_prep_linked_stage_package_findings(
            payload,
            staged_count=staged_count if isinstance(staged_count, int) else None,
            release_ready_candidate=release_ready_candidate if isinstance(release_ready_candidate, bool) else None,
            base_path=base_path,
        )
    )
    findings.extend(
        _gold_reviewer_handoff_release_prep_linked_staging_manifest_findings(
            payload,
            staged_count=staged_count if isinstance(staged_count, int) else None,
            base_path=base_path,
        )
    )
    findings.extend(
        _gold_reviewer_handoff_release_prep_linked_split_plan_findings(
            payload,
            split_plan,
            staged_count=staged_count if isinstance(staged_count, int) else None,
            split_count=split_count if isinstance(split_count, int) else None,
            release_ready_candidate=release_ready_candidate if isinstance(release_ready_candidate, bool) else None,
            base_path=base_path,
        )
    )

    release_package = payload.get("release_package")
    if release_ready is True and not isinstance(release_package, dict):
        findings.append("gold_reviewer_handoff_release_prep_ready_without_release_package")
    if isinstance(release_package, dict):
        manifest_paths = release_package.get("manifest_paths")
        if isinstance(manifest_paths, list) and isinstance(split_count, int) and len(manifest_paths) != split_count:
            findings.append("gold_reviewer_handoff_release_prep_release_package_manifest_count_mismatch")
        release_readiness = release_package.get("release_readiness")
        if isinstance(release_readiness, dict):
            embedded_ready = release_readiness.get("release_ready")
            if isinstance(embedded_ready, bool) and isinstance(release_ready, bool) and embedded_ready != release_ready:
                findings.append("gold_reviewer_handoff_release_prep_release_package_ready_mismatch")
    findings.extend(
        _gold_reviewer_handoff_release_prep_linked_release_package_findings(
            payload,
            release_package,
            split_count=split_count if isinstance(split_count, int) else None,
            release_ready=release_ready if isinstance(release_ready, bool) else None,
            base_path=base_path,
        )
    )
    findings.extend(
        _gold_reviewer_handoff_release_prep_linked_readiness_findings(
            payload,
            release_package,
            split_count=split_count if isinstance(split_count, int) else None,
            release_ready=release_ready if isinstance(release_ready, bool) else None,
            base_path=base_path,
        )
    )
    return findings


