def _optional_non_negative_int_payload_value(payload: dict[str, Any], field_name: str) -> int | Literal["invalid"] | None:
    if field_name not in payload:
        return None
    value = _non_negative_int_payload_value(payload, field_name)
    return value if value is not None else "invalid"


def _non_negative_int_payload_value(payload: dict[str, Any], field_name: str) -> int | None:
    return _coerce_non_negative_int(payload.get(field_name))


def _coerce_non_negative_int(raw_value: Any) -> int | None:
    if isinstance(raw_value, bool):
        return None
    if isinstance(raw_value, int):
        return raw_value if raw_value >= 0 else None
    if isinstance(raw_value, str):
        stripped = raw_value.strip()
        if not stripped:
            return None
        try:
            parsed = int(stripped)
        except ValueError:
            return None
        return parsed if parsed >= 0 else None
    return None


def _roadmap_check_has_actionable_next_action(check: dict[str, Any]) -> bool:
    next_actions = check.get("next_actions")
    return isinstance(next_actions, list) and any(
        isinstance(action, str) and action.strip() for action in next_actions
    )


