        def add_count_map_value(
            *,
            requirement_id: str,
            value: str,
            counts_by_requirement: dict[str, dict[str, int]],
            counts_by_field: dict[str, int],
        ) -> int:
            total = 0
            for raw_pair in value.split(","):
                if ":" not in raw_pair:
                    continue
                raw_field, raw_count = raw_pair.split(":", 1)
                field = raw_field.strip()
                if not field:
                    continue
                try:
                    count = int(raw_count.strip())
                except ValueError:
                    continue
                if count < 0:
                    continue
                total += count
                requirement_counts = counts_by_requirement.setdefault(requirement_id, {})
                requirement_counts[field] = requirement_counts.get(field, 0) + count
                counts_by_field[field] = counts_by_field.get(field, 0) + count
            return total

