def _select_roadmap_completion_suite_from_threshold_adoption_package(
    *,
    threshold_adoption_package_path: Path,
    representative_split: str | None,
) -> tuple[Path, Path, Path]:
    threshold_adoption_package_path = Path(threshold_adoption_package_path).expanduser().resolve()
    package = EvidenceGroundingThresholdAdoptionReviewPackage.model_validate_json(
        threshold_adoption_package_path.read_text(encoding="utf-8")
    )
    comparison_suite_package_path = _resolve_related_review_path(
        package.comparison_suite_package_path,
        base_path=threshold_adoption_package_path,
    )
    suite_package = EvidenceGroundingFixedGoldsetComparisonSuitePackage.model_validate_json(
        comparison_suite_package_path.read_text(encoding="utf-8")
    )
    suite_candidates: list[tuple[Path, EvidenceGroundingFixedGoldsetComparisonSuite, str | None]] = []
    for raw_suite_path in suite_package.comparison_suite_paths:
        suite_path = _resolve_related_review_path(raw_suite_path, base_path=comparison_suite_package_path)
        suite = EvidenceGroundingFixedGoldsetComparisonSuite.model_validate(_load_json_object(suite_path))
        split = _goldset_split_from_comparison_suite(suite_path)
        suite_candidates.append((suite_path, suite, split))
    if not suite_candidates:
        raise ValueError("threshold adoption package comparison-suite package has no comparison_suite_paths")

    requested_split = (representative_split or "eval").strip() or "eval"
    selected_suite_path, _, _ = _select_representative_suite_candidate(
        suite_candidates,
        requested_split=requested_split,
        allow_fallback=representative_split is None,
    )

    adoption_review_paths = [
        _resolve_related_review_path(path, base_path=threshold_adoption_package_path)
        for path in package.threshold_adoption_review_paths
    ]
    if not adoption_review_paths:
        raise ValueError("threshold adoption package has no threshold_adoption_review_paths")
    adoption_by_suite_path: dict[str, Path] = {}
    for adoption_path in adoption_review_paths:
        adoption = EvidenceGroundingThresholdAdoptionReviewReport.model_validate(_load_json_object(adoption_path))
        if adoption.comparison_suite_path:
            adoption_suite_path = _resolve_related_review_path(
                adoption.comparison_suite_path,
                base_path=adoption_path,
            )
            adoption_by_suite_path[str(adoption_suite_path)] = adoption_path
    selected_adoption_path = adoption_by_suite_path.get(str(selected_suite_path))
    if selected_adoption_path is None and len(adoption_review_paths) == 1:
        selected_adoption_path = adoption_review_paths[0]
    if selected_adoption_path is None:
        raise ValueError(
            "threshold adoption package has no adoption review linked to the selected comparison suite: "
            f"{selected_suite_path}"
        )
    calibration_report_path = _resolve_related_review_path(
        package.calibration_report_path,
        base_path=threshold_adoption_package_path,
    )
    return selected_suite_path, selected_adoption_path, calibration_report_path


def _select_representative_suite_candidate(
    candidates: list[tuple[Path, EvidenceGroundingFixedGoldsetComparisonSuite, str | None]],
    *,
    requested_split: str,
    allow_fallback: bool,
) -> tuple[Path, EvidenceGroundingFixedGoldsetComparisonSuite, str | None]:
    split = requested_split.strip()
    for candidate in candidates:
        if _suite_candidate_matches_split(candidate, split):
            return candidate
    if allow_fallback:
        return sorted(candidates, key=lambda item: str(item[0]))[0]
    raise ValueError(f"representative_split did not match any comparison suite: {requested_split}")


def _suite_candidate_matches_split(
    candidate: tuple[Path, EvidenceGroundingFixedGoldsetComparisonSuite, str | None],
    requested_split: str,
) -> bool:
    _, suite, goldset_split = candidate
    requested = requested_split.strip()
    requested_lower = requested.lower()
    labels = [suite.suite_id, goldset_split or ""]
    for label in labels:
        normalized = label.strip()
        if not normalized:
            continue
        normalized_lower = normalized.lower()
        if normalized_lower == requested_lower or normalized_lower.endswith(f"_{requested_lower}"):
            return True
    return False


def _goldset_split_from_comparison_suite(suite_path: Path) -> str | None:
    suite_paths, _ = _roadmap_paths_from_comparison_suite(suite_path)
    candidate_path = suite_paths.get("candidate_benchmark_report_path")
    if candidate_path is None:
        return None
    try:
        candidate = EvidenceGroundingBenchmarkReport.model_validate(_load_json_object(candidate_path))
    except (OSError, ValueError, ValidationError, RuntimeError):
        return None
    return candidate.goldset_split


