def compare_evidence_grounding_scorecard_reports(
    *,
    baseline: Path | dict[str, Any] | EvidenceGroundingScorecard | EvidenceGroundingBenchmarkReport,
    candidate: Path | dict[str, Any] | EvidenceGroundingScorecard | EvidenceGroundingBenchmarkReport,
    tolerance: float = 0.0,
    gate_metric_names: list[str] | None = None,
    gate_preset: EvidenceGroundingMetricGatePreset = "all_comparable",
    threshold_preset: EvidenceGroundingThresholdPreset = "none",
    threshold_metric_values: dict[str, float] | None = None,
    out: Path | None = None,
) -> EvidenceGroundingScorecardComparisonReport:
    baseline_label, baseline_metrics, baseline_failures, baseline_stages, baseline_stage_metrics = (
        _load_comparable_report_parts(baseline)
    )
    candidate_label, candidate_metrics, candidate_failures, candidate_stages, candidate_stage_metrics = (
        _load_comparable_report_parts(candidate)
    )
    context_failures = _benchmark_context_failures(
        baseline_label=baseline_label,
        candidate_label=candidate_label,
    )

    comparisons = _compare_metric_groups(
        baseline_metrics=baseline_metrics,
        candidate_metrics=candidate_metrics,
        tolerance=tolerance,
    )
    failure_count_comparisons = _compare_failure_count_groups(
        baseline_failures=baseline_failures,
        candidate_failures=candidate_failures,
        baseline_stages=baseline_stages,
        candidate_stages=candidate_stages,
    )
    stage_metric_comparisons = _compare_stage_metric_groups(
        baseline_stage_metrics=baseline_stage_metrics,
        candidate_stage_metrics=candidate_stage_metrics,
        tolerance=tolerance,
    )
    correction_reuse_gain = _build_correction_reuse_gain_summary(
        comparisons=comparisons,
        candidate_metrics=candidate_metrics,
    )
    normalized_gate_metric_names, gate_policy = _resolve_metric_gate(
        gate_metric_names=gate_metric_names,
        gate_preset=gate_preset,
    )
    gated_comparisons = _gated_metric_comparisons(comparisons, gate_metric_names=normalized_gate_metric_names)
    gated_stage_metric_comparisons = _gated_stage_metric_comparisons(
        stage_metric_comparisons,
        gate_metric_names=normalized_gate_metric_names,
    )
    threshold_checks, threshold_policy = _build_threshold_checks(
        candidate_metrics=candidate_metrics,
        candidate_stage_metrics=candidate_stage_metrics,
        threshold_preset=threshold_preset,
        threshold_metric_values=threshold_metric_values,
    )

    failed_checks = [comparison.name for comparison in gated_comparisons if not comparison.passed]
    failed_checks.extend(
        f"stage_metric_summary.{comparison.stage}.{comparison.metric_group}.{comparison.name}"
        for comparison in gated_stage_metric_comparisons
        if not comparison.passed
    )
    failed_checks.extend(
        f"{comparison.metric_group}.{comparison.name}"
        for comparison in failure_count_comparisons
        if not comparison.passed
    )
    failed_checks.extend(_threshold_failed_check_name(check) for check in threshold_checks if not check.passed)
    failed_checks.extend(context_failures)
    regressions = [comparison.name for comparison in gated_comparisons if comparison.regression]
    regressions.extend(
        f"stage_metric_summary.{comparison.stage}.{comparison.metric_group}.{comparison.name}"
        for comparison in gated_stage_metric_comparisons
        if comparison.regression
    )
    regressions.extend(
        f"{comparison.metric_group}.{comparison.name}"
        for comparison in failure_count_comparisons
        if comparison.regression
    )
    notes: list[str] = []
    if not comparisons:
        notes.append("no_comparable_metrics")
    if not any(comparison.metric_group == "gold_scored_metrics" for comparison in comparisons):
        notes.append("gold_metrics_unavailable")
    if not any(comparison.metric_group == "runtime_proxy_metrics" for comparison in comparisons):
        notes.append("runtime_proxy_metrics_unavailable")
    if not failure_count_comparisons:
        notes.append("failure_counts_unavailable")
    if not stage_metric_comparisons:
        notes.append("stage_metrics_unavailable")
    if correction_reuse_gain.status == "not_available":
        notes.append("correction_reuse_gain_unavailable")
    if normalized_gate_metric_names:
        notes.append("metric_gate_filter_applied")
    if gate_policy == "p0_gold":
        notes.append("p0_gold_gate_applied")
    if threshold_policy != "none":
        notes.append("threshold_policy_applied")
    if any(check.status == "not_available" for check in threshold_checks):
        notes.append("threshold_metrics_unavailable")
    if context_failures:
        notes.append("benchmark_context_mismatch")

    decision = EvidenceGroundingComparisonDecision(
        passed=bool(comparisons or stage_metric_comparisons) and not failed_checks and not regressions,
        compared_metric_count=len(comparisons) + len(stage_metric_comparisons),
        failed_checks=failed_checks,
        regressions=regressions,
        notes=notes,
    )
    report = EvidenceGroundingScorecardComparisonReport(
        generated_at=datetime.now(timezone.utc),
        baseline=baseline_label,
        candidate=candidate_label,
        thresholds={"tolerance": tolerance},
        gate_policy=gate_policy,
        gate_metric_names=normalized_gate_metric_names,
        threshold_policy=threshold_policy,
        comparisons=comparisons,
        failure_count_comparisons=failure_count_comparisons,
        stage_metric_comparisons=stage_metric_comparisons,
        threshold_checks=threshold_checks,
        correction_reuse_gain=correction_reuse_gain,
        decision=decision,
    )
    if out is not None:
        atomic_write_text(Path(out), report.model_dump_json(indent=2))
    return report


def compare_evidence_grounding_scorecard_reports_from_comparison_suite(
    *,
    comparison_suite_path: Path,
    out: Path,
    tolerance: float = 0.0,
    gate_metric_names: list[str] | None = None,
    gate_preset: EvidenceGroundingMetricGatePreset = "all_comparable",
    threshold_preset: EvidenceGroundingThresholdPreset = "none",
    threshold_metric_values: dict[str, float] | None = None,
    threshold_calibration_report_path: Path | None = None,
) -> EvidenceGroundingScorecardComparisonReport:
    comparison_suite_path = Path(comparison_suite_path).expanduser().resolve()
    suite_paths, suite_warnings = _roadmap_paths_from_comparison_suite(comparison_suite_path)
    baseline_report_path = suite_paths.get("baseline_benchmark_report_path")
    candidate_report_path = suite_paths.get("candidate_benchmark_report_path")
    missing = [
        name
        for name, path in (
            ("baseline_benchmark_report_path", baseline_report_path),
            ("candidate_benchmark_report_path", candidate_report_path),
        )
        if path is None
    ]
    if missing:
        details = "; ".join(suite_warnings) if suite_warnings else "comparison suite is missing benchmark report paths"
        raise ValueError(f"comparison suite cannot be compared; missing {', '.join(missing)} ({details})")

    return compare_evidence_grounding_scorecard_reports(
        baseline=baseline_report_path,
        candidate=candidate_report_path,
        tolerance=tolerance,
        gate_metric_names=gate_metric_names,
        gate_preset=gate_preset,
        threshold_preset=threshold_preset,
        threshold_metric_values=_merge_threshold_metric_values(
            threshold_calibration_report_path=threshold_calibration_report_path,
            threshold_metric_values=threshold_metric_values,
        ),
        out=out,
    )


def _merge_threshold_metric_values(
    *,
    threshold_calibration_report_path: Path | None,
    threshold_metric_values: dict[str, float] | None,
) -> dict[str, float] | None:
    values: dict[str, float] = {}
    if threshold_calibration_report_path is not None:
        values.update(threshold_metric_values_from_calibration_report(Path(threshold_calibration_report_path)))
    if threshold_metric_values:
        values.update(threshold_metric_values)
    return values or None


def _unique_candidate_configs(
    scorecard_items: list[EvidenceGroundingBenchmarkScorecardItem],
) -> list[EvidenceGroundingCandidateConfig]:
    configs: list[EvidenceGroundingCandidateConfig] = []
    seen: set[str] = set()
    for item in scorecard_items:
        config = item.candidate_config
        if config is None or not config.has_lineage():
            continue
        key = json.dumps(config.model_dump(mode="json", exclude_none=True), sort_keys=True)
        if key in seen:
            continue
        seen.add(key)
        configs.append(config)
    return configs


def _resolve_run_dir(raw_run_dir: str, *, base_dir: Path | None) -> Path:
    path = Path(raw_run_dir).expanduser()
    if not path.is_absolute() and base_dir is not None:
        path = base_dir / path
    return path.resolve()


def _build_fixed_goldset_run_readiness_lane(
    *,
    lane: Literal["baseline", "candidate"],
    run_root: Path,
    gold_records: list[dict[str, Any]],
    run_dir_template: str,
    run_dir_map: Mapping[str, str | Path] | None,
    required_artifacts: list[str],
    optional_artifacts: list[str],
) -> EvidenceGroundingFixedGoldsetRunReadinessLaneSummary:
    items: list[EvidenceGroundingFixedGoldsetRunReadinessItem] = []
    for record in gold_records:
        paper_id = str(record["paper_id"])
        run_dir = _benchmark_manifest_run_dir_for_paper(
            paper_id,
            run_root=run_root,
            run_dir_template=run_dir_template,
            run_dir_map=run_dir_map,
        ).resolve()
        run_dir_exists = run_dir.is_dir()
        present_required = [name for name in required_artifacts if (run_dir / name).is_file()]
        missing_required = [name for name in required_artifacts if name not in present_required]
        malformed_required = _malformed_required_artifacts(run_dir, present_required)
        present_optional = [name for name in optional_artifacts if (run_dir / name).is_file()]
        missing_optional = [name for name in optional_artifacts if name not in present_optional]
        declared_paper_ids: set[str] = set()
        identity_metadata_error_count = 0
        if not run_dir_exists:
            present_required = []
            missing_required = list(required_artifacts)
            malformed_required = []
            present_optional = []
            missing_optional = list(optional_artifacts)
        else:
            declared_paper_ids, identity_metadata_error_count = _run_dir_declared_paper_identity(run_dir)
        run_identity_conflict = len(declared_paper_ids) > 1
        run_identity_match = paper_id in declared_paper_ids if declared_paper_ids else None
        status = (
            "pass"
            if (
                run_dir_exists
                and not missing_required
                and not malformed_required
                and identity_metadata_error_count == 0
                and not run_identity_conflict
                and run_identity_match is not False
            )
            else "fail"
        )
        items.append(
            EvidenceGroundingFixedGoldsetRunReadinessItem(
                paper_id=paper_id,
                run_dir=str(run_dir),
                status=status,
                run_dir_exists=run_dir_exists,
                declared_paper_ids=sorted(declared_paper_ids),
                run_identity_match=run_identity_match,
                run_identity_conflict=run_identity_conflict,
                run_identity_metadata_error_count=identity_metadata_error_count,
                present_required_artifacts=present_required,
                missing_required_artifacts=missing_required,
                malformed_required_artifacts=malformed_required,
                present_optional_artifacts=present_optional,
                missing_optional_artifacts=missing_optional,
                gold_readiness_status=record.get("readiness_status"),
                gold_readiness_reason_codes=record.get("readiness_reason_codes", []),
            )
        )

    return EvidenceGroundingFixedGoldsetRunReadinessLaneSummary(
        lane=lane,
        run_root=str(run_root),
        item_count=len(items),
        pass_count=sum(1 for item in items if item.status == "pass"),
        fail_count=sum(1 for item in items if item.status == "fail"),
        missing_run_count=sum(1 for item in items if not item.run_dir_exists),
        missing_required_artifact_count=sum(len(item.missing_required_artifacts) for item in items),
        malformed_required_artifact_count=sum(len(item.malformed_required_artifacts) for item in items),
        identity_mismatch_count=sum(1 for item in items if item.run_identity_match is False),
        identity_conflict_count=sum(1 for item in items if item.run_identity_conflict),
        identity_metadata_error_count=sum(item.run_identity_metadata_error_count for item in items),
        items=items,
    )


def _benchmark_manifest_run_dir_for_paper(
    paper_id: str,
    *,
    run_root: Path,
    run_dir_template: str,
    run_dir_map: Mapping[str, str | Path] | None,
) -> Path:
    if run_dir_map is not None and paper_id in run_dir_map:
        mapped = Path(run_dir_map[paper_id]).expanduser()
        return mapped if mapped.is_absolute() else (run_root / mapped)
    return run_root / _format_run_dir_template(run_dir_template, paper_id=paper_id)


def _benchmark_manifest_package_manifest_sources(
    package: EvidenceGroundingBenchmarkManifestPackage,
    *,
    base_path: Path,
) -> list[tuple[Path, EvidenceGroundingBenchmarkManifest]]:
    if package.benchmark_manifest_paths:
        sources: list[tuple[Path, EvidenceGroundingBenchmarkManifest]] = []
        for raw_path in package.benchmark_manifest_paths:
            manifest_path = _resolve_related_review_path(raw_path, base_path=base_path)
            sources.append((manifest_path, load_evidence_grounding_benchmark_manifest(manifest_path)))
        return sources
    return [
        (base_path.parent / f"embedded-benchmark-manifest-{index}.json", manifest)
        for index, manifest in enumerate(package.benchmark_manifests)
    ]


def _merge_benchmark_manifest_item_run_dirs(
    run_dir_map: dict[str, Path],
    manifest: EvidenceGroundingBenchmarkManifest,
    *,
    base_path: Path,
) -> None:
    base_dir = Path(base_path).expanduser().resolve().parent
    for item in manifest.items:
        if not item.paper_id:
            continue
        run_dir = Path(item.run_dir).expanduser()
        resolved_run_dir = run_dir.resolve() if run_dir.is_absolute() else (base_dir / run_dir).resolve()
        existing = run_dir_map.get(item.paper_id)
        if existing is not None and existing != resolved_run_dir:
            raise ValueError(f"duplicate_run_dir_map_paper_id: {item.paper_id}")
        run_dir_map[item.paper_id] = resolved_run_dir


def _benchmark_manifest_item_run_dir_map(
    manifest: EvidenceGroundingBenchmarkManifest,
    *,
    base_path: Path,
) -> dict[str, Path]:
    base_dir = Path(base_path).expanduser().resolve().parent
    run_dir_map: dict[str, Path] = {}
    for item in manifest.items:
        if not item.paper_id:
            continue
        run_dir = Path(item.run_dir).expanduser()
        run_dir_map[item.paper_id] = run_dir if run_dir.is_absolute() else (base_dir / run_dir)
    return run_dir_map


def _load_benchmark_run_dir_map(path: Path) -> dict[str, Path]:
    path = Path(path).expanduser().resolve()
    payload = json.loads(path.read_text(encoding="utf-8"))
    base_dir = path.parent
    raw_items: list[tuple[str, Any]] = []
    if isinstance(payload, dict):
        for paper_id, value in payload.items():
            raw_items.append((str(paper_id), value))
    elif isinstance(payload, list):
        for item in payload:
            if not isinstance(item, dict):
                raise ValueError("run dir map list items must be objects")
            paper_id = str(item.get("paper_id") or "").strip()
            raw_items.append((paper_id, item.get("run_dir")))
    else:
        raise ValueError("run dir map must be a JSON object or list of {paper_id, run_dir} objects")

    run_dir_map: dict[str, Path] = {}
    for paper_id, raw_value in raw_items:
        paper_id = paper_id.strip()
        if not paper_id:
            raise ValueError("run dir map entries require paper_id")
        if isinstance(raw_value, dict):
            raw_value = raw_value.get("run_dir")
        run_dir_text = str(raw_value or "").strip()
        if not run_dir_text:
            raise ValueError(f"run dir map entry requires run_dir: paper_id={paper_id}")
        run_dir = Path(run_dir_text).expanduser()
        run_dir_map[paper_id] = run_dir if run_dir.is_absolute() else (base_dir / run_dir)
    return run_dir_map


def _format_run_dir_template(template: str, *, paper_id: str) -> str:
    return template.format(paper_id=paper_id, safe_paper_id=_safe_path_segment(paper_id))


def _manifest_path_string(path: Path, *, base_dir: Path | None) -> str:
    path = Path(path).expanduser().resolve()
    if base_dir is None:
        return str(path)
    return os.path.relpath(path, start=base_dir)


def _safe_path_segment(value: str) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9._-]", "_", value)
    cleaned = re.sub(r"_+", "_", cleaned).strip("_")
    return cleaned or "paper"


def _normalize_artifact_names(values: list[str] | None) -> list[str]:
    if not values:
        return []
    normalized: list[str] = []
    seen: set[str] = set()
    for raw_value in values:
        value = str(raw_value or "").strip()
        if not value or value in seen:
            continue
        seen.add(value)
        normalized.append(value)
    return normalized


def _validate_goldset_manifest_reference(
    manifest: EvidenceGroundingBenchmarkManifest,
    *,
    base_dir: Path | None,
) -> tuple[dict[str, Any] | None, list[str]]:
    if not manifest.goldset_manifest_path:
        return None, []

    goldset_manifest_path = Path(manifest.goldset_manifest_path).expanduser()
    if not goldset_manifest_path.is_absolute() and base_dir is not None:
        goldset_manifest_path = base_dir / goldset_manifest_path
    goldset_manifest_path = goldset_manifest_path.resolve()

    if not goldset_manifest_path.exists():
        return None, [f"goldset_manifest_path_missing: path={goldset_manifest_path}"]

    summary = validate_gold_paths([goldset_manifest_path])
    warnings: list[str] = []
    if summary["manifest_count"] != 1:
        warnings.append(
            "goldset_manifest_contract_missing: "
            f"path={goldset_manifest_path} manifest_count={summary['manifest_count']}"
        )
    if summary["invalid_count"]:
        first_error = summary["invalid"][0]["error"] if summary["invalid"] else "unknown validation error"
        warnings.append(
            "goldset_manifest_validation_failed: "
            f"path={goldset_manifest_path} invalid_count={summary['invalid_count']} first_error={first_error}"
        )

    validated_manifests = summary.get("manifests") or []
    if not validated_manifests:
        return summary, warnings

    validated_manifest = validated_manifests[0]
    if manifest.goldset_id and validated_manifest.get("goldset_id") != manifest.goldset_id:
        warnings.append(
            "goldset_manifest_id_mismatch: "
            f"benchmark_goldset_id={manifest.goldset_id} "
            f"manifest_goldset_id={validated_manifest.get('goldset_id')}"
        )
    if manifest.goldset_split and validated_manifest.get("goldset_split") != manifest.goldset_split:
        warnings.append(
            "goldset_manifest_split_mismatch: "
            f"benchmark_goldset_split={manifest.goldset_split} "
            f"manifest_goldset_split={validated_manifest.get('goldset_split')}"
        )
    return summary, warnings


def _load_gold_records_by_paper_id(
    goldset_validation: dict[str, Any] | None,
    *,
    warnings: list[str],
) -> dict[str, PaperUnderstandingGold]:
    if goldset_validation is None or goldset_validation.get("manifest_count") != 1:
        return {}
    records: dict[str, PaperUnderstandingGold] = {}
    for item in goldset_validation.get("valid", []):
        paper_id = str(item.get("paper_id") or "").strip()
        path = str(item.get("path") or "").strip()
        if not paper_id or not path:
            continue
        record, error = validate_gold_path(Path(path))
        if record is None:
            warnings.append(f"goldset_record_load_failed: paper_id={paper_id} path={path} error={error}")
            continue
        records[paper_id] = record
    return records


def _fixed_gold_source(
    *,
    manifest: EvidenceGroundingBenchmarkManifest,
    paper_id: str | None,
    gold: PaperUnderstandingGold | None,
) -> str | None:
    if gold is None:
        return None
    if manifest.goldset_manifest_path:
        if paper_id:
            return f"{manifest.goldset_manifest_path}#{paper_id}"
        return manifest.goldset_manifest_path
    return "paper_understanding_gold_manifest"


def _build_goldset_coverage_summary(
    goldset_validation: dict[str, Any] | None,
    *,
    scorecard_items: list[EvidenceGroundingBenchmarkScorecardItem],
) -> dict[str, Any]:
    if goldset_validation is None or goldset_validation.get("manifest_count") != 1:
        return {
            "goldset_item_count": None,
            "goldset_covered_paper_count": None,
            "goldset_missing_paper_ids": [],
            "goldset_extra_paper_ids": [],
            "goldset_readiness_pass_count": None,
            "goldset_readiness_warn_count": None,
            "goldset_readiness_fail_count": None,
            "goldset_not_ready_paper_ids": [],
            "warnings": [],
        }

    gold_paper_ids = {
        str(item.get("paper_id", "")).strip()
        for item in goldset_validation.get("valid", [])
        if str(item.get("paper_id", "")).strip()
    }
    scored_paper_ids = {item.paper_id.strip() for item in scorecard_items if item.paper_id.strip()}
    missing_paper_ids = sorted(gold_paper_ids - scored_paper_ids)
    extra_paper_ids = sorted(scored_paper_ids - gold_paper_ids)
    readiness_summary = goldset_validation.get("readiness", {})
    not_ready_paper_ids = sorted(
        str(item.get("paper_id", "")).strip()
        for item in goldset_validation.get("valid", [])
        if str(item.get("paper_id", "")).strip() and item.get("readiness_status") != "pass"
    )
    warnings: list[str] = []
    if missing_paper_ids:
        warnings.append(
            "goldset_manifest_coverage_missing: "
            f"count={len(missing_paper_ids)} paper_ids={','.join(missing_paper_ids)}"
        )
    if extra_paper_ids:
        warnings.append(
            "goldset_manifest_coverage_extra: "
            f"count={len(extra_paper_ids)} paper_ids={','.join(extra_paper_ids)}"
        )
    if not_ready_paper_ids:
        warnings.append(
            "goldset_manifest_readiness_not_pass: "
            f"count={len(not_ready_paper_ids)} paper_ids={','.join(not_ready_paper_ids)}"
        )
    return {
        "goldset_item_count": len(gold_paper_ids),
        "goldset_covered_paper_count": len(gold_paper_ids & scored_paper_ids),
        "goldset_missing_paper_ids": missing_paper_ids,
        "goldset_extra_paper_ids": extra_paper_ids,
        "goldset_readiness_pass_count": readiness_summary.get("pass_count", 0),
        "goldset_readiness_warn_count": readiness_summary.get("warn_count", 0),
        "goldset_readiness_fail_count": readiness_summary.get("fail_count", 0),
        "goldset_not_ready_paper_ids": not_ready_paper_ids,
        "warnings": warnings,
    }


def _build_scorecard_readiness_summary(
    scorecard_items: list[EvidenceGroundingBenchmarkScorecardItem],
) -> dict[str, Any]:
    pass_count = sum(1 for item in scorecard_items if item.scorecard.readiness_status == "pass")
    warn_items = [item for item in scorecard_items if item.scorecard.readiness_status == "warn"]
    fail_items = [item for item in scorecard_items if item.scorecard.readiness_status == "fail"]
    not_ready_candidate_ids = sorted(
        item.candidate_id
        for item in [*warn_items, *fail_items]
        if str(item.candidate_id or "").strip()
    )
    warnings: list[str] = []
    if warn_items:
        warnings.append(
            "scorecard_readiness_warnings_present: "
            f"count={len(warn_items)} candidate_ids={','.join(sorted(item.candidate_id for item in warn_items))}"
        )
    if fail_items:
        warnings.append(
            "scorecard_readiness_failures_present: "
            f"count={len(fail_items)} candidate_ids={','.join(sorted(item.candidate_id for item in fail_items))}"
        )
    return {
        "pass_count": pass_count,
        "warn_count": len(warn_items),
        "fail_count": len(fail_items),
        "not_ready_candidate_ids": not_ready_candidate_ids,
        "warnings": warnings,
    }


def _build_benchmark_package_scorecard_readiness_summary(
    benchmark_reports: list[EvidenceGroundingBenchmarkReport],
) -> dict[str, Any]:
    pass_count = sum(report.scorecard_readiness_pass_count for report in benchmark_reports)
    warn_count = sum(report.scorecard_readiness_warn_count for report in benchmark_reports)
    fail_count = sum(report.scorecard_readiness_fail_count for report in benchmark_reports)
    not_ready_candidate_ids = sorted(
        {
            f"{report.benchmark_id}:{candidate_id}"
            for report in benchmark_reports
            for candidate_id in report.scorecard_not_ready_candidate_ids
            if str(candidate_id or "").strip()
        }
    )
    warnings: list[str] = []
    if warn_count:
        warnings.append(
            "scorecard_readiness_warnings_present: "
            f"count={warn_count} candidate_ids={','.join(not_ready_candidate_ids) or '-'}"
        )
    if fail_count:
        warnings.append(
            "scorecard_readiness_failures_present: "
            f"count={fail_count} candidate_ids={','.join(not_ready_candidate_ids) or '-'}"
        )
    return {
        "pass_count": pass_count,
        "warn_count": warn_count,
        "fail_count": fail_count,
        "not_ready_candidate_ids": not_ready_candidate_ids,
        "warnings": warnings,
    }


