def _benchmark_run_package_missing_papers_by_split(raw_path: str, *, base_path: Path) -> dict[str, list[str]]:
    try:
        package_path = _resolve_related_review_path(raw_path, base_path=base_path)
        package = EvidenceGroundingBenchmarkRunPackage.model_validate(_load_json_object(package_path))
    except (OSError, ValueError, ValidationError, RuntimeError):
        return {}
    missing_by_split: dict[str, set[str]] = {}
    reports = list(package.benchmark_reports)
    if not reports:
        for raw_report_path in package.benchmark_report_paths:
            try:
                report_path = _resolve_related_review_path(raw_report_path, base_path=package_path)
                reports.append(EvidenceGroundingBenchmarkReport.model_validate(_load_json_object(report_path)))
            except (OSError, ValueError, ValidationError, RuntimeError):
                continue
    for report in reports:
        if not report.goldset_missing_paper_ids:
            continue
        split = (report.goldset_split or report.goldset_id or report.benchmark_id or "unknown").strip() or "unknown"
        missing_by_split.setdefault(split, set()).update(report.goldset_missing_paper_ids)
    return {split: sorted(paper_ids) for split, paper_ids in sorted(missing_by_split.items())}


